rtl/cache/data_cache.v.text:
`timescale 1ns/1ps

module data_cache #(
    parameter integer SETS = 16,
    parameter integer WORDS_PER_LINE = 4
) (
    input  wire        clk,
    input  wire        rst,

    input  wire        cpu_valid,
    input  wire        cpu_write,
    input  wire [31:0] cpu_addr,
    input  wire [31:0] cpu_wdata,
    input  wire [3:0]  cpu_wstrb,
    output wire        cpu_ready,
    output reg  [31:0] cpu_rdata,

    output wire        mem_valid,
    output wire        mem_write,
    output wire [31:0] mem_addr,
    output wire [31:0] mem_wdata,
    output wire [3:0]  mem_wstrb,
    input  wire        mem_ready,
    input  wire [31:0] mem_rdata,

    output reg  [31:0] hit_count,
    output reg  [31:0] miss_count,
    output reg  [31:0] writeback_count
);
    localparam integer SET_INDEX_BITS = (SETS > 1) ? $clog2(SETS) : 1;
    localparam integer WORD_INDEX_BITS =
        (WORDS_PER_LINE > 1) ? $clog2(WORDS_PER_LINE) : 1;
    localparam integer LINE_OFFSET_BITS = $clog2(WORDS_PER_LINE) + 2;
    localparam integer DATA_WORDS = SETS * WORDS_PER_LINE;

    localparam [2:0] STATE_IDLE      = 3'd0;
    localparam [2:0] STATE_LOOKUP    = 3'd1;
    localparam [2:0] STATE_WRITEBACK = 3'd2;
    localparam [2:0] STATE_REFILL    = 3'd3;
    localparam [2:0] STATE_COMPLETE  = 3'd4;

    reg [2:0] state;

    reg [31:0] tag_way0 [0:SETS-1];
    reg [31:0] tag_way1 [0:SETS-1];
    reg        valid_way0 [0:SETS-1];
    reg        valid_way1 [0:SETS-1];
    reg        dirty_way0 [0:SETS-1];
    reg        dirty_way1 [0:SETS-1];
    reg        lru_way [0:SETS-1];
    reg [31:0] data_way0 [0:DATA_WORDS-1];
    reg [31:0] data_way1 [0:DATA_WORDS-1];

    reg        request_write;
    reg [31:0] request_addr;
    reg [31:0] request_wdata;
    reg [3:0]  request_wstrb;

    reg        victim_way;
    reg [31:0] victim_line_number;
    reg [WORD_INDEX_BITS-1:0] transfer_word;
    reg [31:0] refill_cpu_word;

    wire [31:0] request_line_number;
    wire [SET_INDEX_BITS-1:0] request_set;
    wire [WORD_INDEX_BITS-1:0] request_word;
    wire [31:0] request_line_base;
    wire hit_way0;
    wire hit_way1;
    wire selected_victim_way;
    wire selected_victim_valid;
    wire selected_victim_dirty;
    wire [31:0] selected_victim_line;
    wire [31:0] writeback_line_base;
    wire [31:0] transfer_byte_offset;
    wire [31:0] selected_writeback_data;

    integer reset_index;

    generate
        if ((SETS <= 0) || ((SETS & (SETS - 1)) != 0)) begin : invalid_sets
            initial begin
                $display("DATA_CACHE_PARAMETER_ERROR SETS=%0d expected positive power of two",
                         SETS);
                $error("data_cache has an invalid SETS parameter");
                $finish;
            end
        end else if ((WORDS_PER_LINE <= 0)
                     || ((WORDS_PER_LINE & (WORDS_PER_LINE - 1)) != 0)) begin : invalid_words_per_line
            initial begin
                $display("DATA_CACHE_PARAMETER_ERROR WORDS_PER_LINE=%0d expected positive power of two",
                         WORDS_PER_LINE);
                $error("data_cache has an invalid WORDS_PER_LINE parameter");
                $finish;
            end
        end
    endgenerate

    function [31:0] merge_bytes;
        input [31:0] previous;
        input [31:0] replacement;
        input [3:0] strobes;
        integer byte_lane;
        begin
            merge_bytes = previous;
            for (byte_lane = 0; byte_lane < 4; byte_lane = byte_lane + 1) begin
                if (strobes[byte_lane])
                    merge_bytes[byte_lane*8 +: 8] =
                        replacement[byte_lane*8 +: 8];
            end
        end
    endfunction

    assign request_line_number = request_addr >> LINE_OFFSET_BITS;
    assign request_set = request_line_number & (SETS - 1);
    assign request_word = (request_addr >> 2) & (WORDS_PER_LINE - 1);
    assign request_line_base = request_line_number << LINE_OFFSET_BITS;

    assign hit_way0 = valid_way0[request_set]
                   && (tag_way0[request_set] == request_line_number);
    assign hit_way1 = valid_way1[request_set]
                   && (tag_way1[request_set] == request_line_number);

    assign selected_victim_way = !valid_way0[request_set] ? 1'b0
                               : !valid_way1[request_set] ? 1'b1
                               : lru_way[request_set];
    assign selected_victim_valid = selected_victim_way
                                 ? valid_way1[request_set]
                                 : valid_way0[request_set];
    assign selected_victim_dirty = selected_victim_way
                                 ? dirty_way1[request_set]
                                 : dirty_way0[request_set];
    assign selected_victim_line = selected_victim_way
                                ? tag_way1[request_set]
                                : tag_way0[request_set];

    assign writeback_line_base = victim_line_number << LINE_OFFSET_BITS;
    assign transfer_byte_offset = transfer_word << 2;
    assign selected_writeback_data = victim_way
        ? data_way1[request_set * WORDS_PER_LINE + transfer_word]
        : data_way0[request_set * WORDS_PER_LINE + transfer_word];

    assign cpu_ready = !rst && (state == STATE_COMPLETE);
    assign mem_valid = !rst
                    && ((state == STATE_WRITEBACK) || (state == STATE_REFILL));
    assign mem_write = (state == STATE_WRITEBACK);
    assign mem_addr = (state == STATE_WRITEBACK)
                    ? (writeback_line_base + transfer_byte_offset)
                    : (request_line_base + transfer_byte_offset);
    assign mem_wdata = (state == STATE_WRITEBACK)
                     ? selected_writeback_data : 32'b0;
    assign mem_wstrb = (state == STATE_WRITEBACK) ? 4'b1111 : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            state <= STATE_IDLE;
            request_write <= 1'b0;
            request_addr <= 32'b0;
            request_wdata <= 32'b0;
            request_wstrb <= 4'b0;
            victim_way <= 1'b0;
            victim_line_number <= 32'b0;
            transfer_word <= {WORD_INDEX_BITS{1'b0}};
            refill_cpu_word <= 32'b0;
            cpu_rdata <= 32'b0;
            hit_count <= 32'b0;
            miss_count <= 32'b0;
            writeback_count <= 32'b0;
            for (reset_index = 0; reset_index < SETS;
                 reset_index = reset_index + 1) begin
                valid_way0[reset_index] <= 1'b0;
                valid_way1[reset_index] <= 1'b0;
                dirty_way0[reset_index] <= 1'b0;
                dirty_way1[reset_index] <= 1'b0;
                lru_way[reset_index] <= 1'b0;
            end
        end else begin
            case (state)
                STATE_IDLE: begin
                    if (cpu_valid) begin
                        request_write <= cpu_write;
                        request_addr <= cpu_addr;
                        request_wdata <= cpu_wdata;
                        request_wstrb <= cpu_wstrb;
                        state <= STATE_LOOKUP;
                    end
                end

                STATE_LOOKUP: begin
                    if (hit_way0) begin
                        hit_count <= hit_count + 1'b1;
                        lru_way[request_set] <= 1'b1;
                        if (request_write) begin
                            data_way0[request_set * WORDS_PER_LINE
                                      + request_word] <=
                                merge_bytes(
                                    data_way0[request_set * WORDS_PER_LINE
                                              + request_word],
                                    request_wdata, request_wstrb);
                            dirty_way0[request_set] <= 1'b1;
                        end else begin
                            cpu_rdata <= data_way0[
                                request_set * WORDS_PER_LINE + request_word];
                        end
                        state <= STATE_COMPLETE;
                    end else if (hit_way1) begin
                        hit_count <= hit_count + 1'b1;
                        lru_way[request_set] <= 1'b0;
                        if (request_write) begin
                            data_way1[request_set * WORDS_PER_LINE
                                      + request_word] <=
                                merge_bytes(
                                    data_way1[request_set * WORDS_PER_LINE
                                              + request_word],
                                    request_wdata, request_wstrb);
                            dirty_way1[request_set] <= 1'b1;
                        end else begin
                            cpu_rdata <= data_way1[
                                request_set * WORDS_PER_LINE + request_word];
                        end
                        state <= STATE_COMPLETE;
                    end else begin
                        miss_count <= miss_count + 1'b1;
                        victim_way <= selected_victim_way;
                        victim_line_number <= selected_victim_line;
                        transfer_word <= {WORD_INDEX_BITS{1'b0}};
                        if (selected_victim_valid && selected_victim_dirty)
                            state <= STATE_WRITEBACK;
                        else
                            state <= STATE_REFILL;
                    end
                end

                STATE_WRITEBACK: begin
                    if (mem_ready) begin
                        if (transfer_word == WORDS_PER_LINE - 1) begin
                            writeback_count <= writeback_count + 1'b1;
                            transfer_word <= {WORD_INDEX_BITS{1'b0}};
                            state <= STATE_REFILL;
                        end else begin
                            transfer_word <= transfer_word + 1'b1;
                        end
                    end
                end

                STATE_REFILL: begin
                    if (mem_ready) begin
                        if (victim_way) begin
                            data_way1[request_set * WORDS_PER_LINE
                                      + transfer_word] <=
                                (request_write && (request_word == transfer_word))
                                ? merge_bytes(mem_rdata, request_wdata,
                                              request_wstrb)
                                : mem_rdata;
                        end else begin
                            data_way0[request_set * WORDS_PER_LINE
                                      + transfer_word] <=
                                (request_write && (request_word == transfer_word))
                                ? merge_bytes(mem_rdata, request_wdata,
                                              request_wstrb)
                                : mem_rdata;
                        end

                        if (request_word == transfer_word)
                            refill_cpu_word <= mem_rdata;

                        if (transfer_word == WORDS_PER_LINE - 1) begin
                            if (victim_way) begin
                                tag_way1[request_set] <= request_line_number;
                                valid_way1[request_set] <= 1'b1;
                                dirty_way1[request_set] <= request_write;
                            end else begin
                                tag_way0[request_set] <= request_line_number;
                                valid_way0[request_set] <= 1'b1;
                                dirty_way0[request_set] <= request_write;
                            end
                            lru_way[request_set] <= ~victim_way;
                            if (!request_write) begin
                                cpu_rdata <= (request_word == transfer_word)
                                           ? mem_rdata : refill_cpu_word;
                            end
                            state <= STATE_COMPLETE;
                        end else begin
                            transfer_word <= transfer_word + 1'b1;
                        end
                    end
                end

                STATE_COMPLETE: begin
                    state <= STATE_IDLE;
                end

                default: begin
                    state <= STATE_IDLE;
                end
            endcase
        end
    end
endmodule

rtl/core/cp0.v.text:
`timescale 1ns/1ps
module cp0(
 input wire clk,rst,
 input wire [4:0] read_addr,write_addr,
 input wire [31:0] write_data,
 input wire write_valid,
 output wire [31:0] read_data,
 input wire exception_valid,
 input wire [4:0] exception_code,
 input wire [31:0] exception_pc,exception_badvaddr,
 input wire exception_bd,eret,
 input wire [5:0] hw_irq,
 output wire [31:0] status,cause,epc,badvaddr,
 output wire irq_pending
);
reg [31:0] status_reg,epc_reg,badvaddr_reg,count_reg,compare_reg;
reg [4:0] code_reg;
reg bd_reg,timer_pending;
reg [1:0] software_pending;
wire [7:0] pending={hw_irq[5] | timer_pending,hw_irq[4:0],software_pending};
wire software_write_accepted=write_valid && !exception_valid && !eret;
wire count_write_accepted=software_write_accepted && write_addr==9;
wire compare_write_accepted=software_write_accepted && write_addr==11;
wire [31:0] count_next=count_write_accepted?write_data:count_reg+32'd1;
assign status=status_reg;
assign epc=epc_reg;
assign badvaddr=badvaddr_reg;
assign cause={bd_reg,timer_pending,14'b0,pending,1'b0,code_reg,2'b0};
assign irq_pending=status_reg[0] && !status_reg[1] && |(pending & status_reg[15:8]);
assign read_data=(read_addr==8)?badvaddr_reg:
                 (read_addr==9)?count_reg:
                 (read_addr==11)?compare_reg:
                 (read_addr==12)?status_reg:
                 (read_addr==13)?cause:
                 (read_addr==14)?epc_reg:
                 (read_addr==15)?32'h00018000:32'b0;
always @(posedge clk) begin
 if(rst) begin
  status_reg<=32'h00400000;epc_reg<=0;badvaddr_reg<=0;
  count_reg<=0;compare_reg<=0;code_reg<=0;bd_reg<=0;
 timer_pending<=0;software_pending<=0;
 end else begin
  count_reg<=count_next;
  if(compare_write_accepted)timer_pending<=0;
  else if(count_next==compare_reg)timer_pending<=1;
  if(exception_valid) begin
   status_reg[1]<=1;
   code_reg<=exception_code;
   if(!status_reg[1]) begin epc_reg<=exception_pc;bd_reg<=exception_bd;end
   if(exception_code==4 || exception_code==5)badvaddr_reg<=exception_badvaddr;
  end else if(eret) begin
   status_reg[1]<=0;
  end else if(write_valid) begin
   case(write_addr)
    9: begin end
    11: compare_reg<=write_data;
    12: status_reg<=write_data;
    13: software_pending<=write_data[9:8];
    14: epc_reg<=write_data;
    default: begin end
   endcase
  end
 end
end
endmodule

rtl/core/pipeline_cpu.v.text:
`timescale 1ns/1ps
// Five stage, in-order MIPS teaching pipeline. See docs/pipeline.md.
module pipeline_cpu #(parameter RESET_PC=32'hbfc00000, EXCEPTION_PC=32'hbfc00380)(
 input wire clk,rst,
 output wire [31:0] imem_addr,input wire [31:0] imem_rdata,
 output wire dmem_valid,dmem_write,output wire [31:0] dmem_addr,dmem_wdata,
 output wire [3:0] dmem_wstrb,input wire dmem_ready,input wire [31:0] dmem_rdata,
 input wire [5:0] hw_irq,
 output wire trace_valid,output wire [31:0] trace_pc,trace_instr,
 output wire trace_we,output wire [4:0] trace_rd,output wire [31:0] trace_wdata,
 output wire [3:0] trace_mem_we,output wire [31:0] trace_mem_addr,trace_mem_wdata,
 output wire exception_valid,output wire [4:0] exception_code,
 output wire [31:0] exception_epc,output wire exception_bd,
 output reg [31:0] cycle_count,retired_count,stall_count
);
 reg [31:0] regs[0:31];integer n;
 reg [31:0] if_pc;
 reg id_valid,ex_valid,mem_valid,wb_valid;
 reg [31:0] id_pc,id_instr,ex_pc,ex_instr,mem_pc,mem_instr,wb_pc,wb_instr;
 reg ex_bd;reg [31:0] ex_branch_pc;
 reg mem_we,mem_load,mem_store,mem_fault,mem_bd,mem_cpwrite,mem_eret;
 reg [4:0] mem_rd,mem_code,mem_cpaddr;reg [31:0] mem_value,mem_addr,mem_data,mem_epc,mem_bad;
 reg [3:0] mem_strobe;
 reg wb_we,wb_fault,wb_bd,wb_cpwrite,wb_eret;
 reg [4:0] wb_rd,wb_code,wb_cpaddr;reg [31:0] wb_value,wb_addr,wb_data,wb_epc,wb_bad;
 reg [3:0] wb_strobe;
 reg trap_wait;
 wire if_valid=!rst&&!trap_wait;
 wire [31:0] if_instr=imem_rdata;
 wire [5:0] op=ex_instr[31:26],fn=ex_instr[5:0];
 wire [4:0] rs=ex_instr[25:21],rt=ex_instr[20:16],rd=ex_instr[15:11],sa=ex_instr[10:6];
 wire [31:0] simm={{16{ex_instr[15]}},ex_instr[15:0]},zimm={16'b0,ex_instr[15:0]};
 reg [31:0] a,b;
 always @* begin
  a=rs==0?0:regs[rs];b=rt==0?0:regs[rt];
  if(wb_valid&&wb_we&&!wb_fault&&wb_rd!=0)begin if(wb_rd==rs)a=wb_value;if(wb_rd==rt)b=wb_value;end
  if(mem_valid&&mem_we&&!mem_load&&!mem_fault&&mem_rd!=0)begin if(mem_rd==rs)a=mem_value;if(mem_rd==rt)b=mem_value;end
 end
 wire [31:0] pc4=ex_pc+4,pc8=ex_pc+8,effective_addr=a+simm;
 reg write_reg,control_transfer,take_branch,illegal,is_load,is_store,cpwrite,is_eret,fault;
 reg [4:0] write_rd,fault_code;
 reg [31:0] write_data,transfer_target,store_data,fault_bad;
 reg [3:0] store_strobe;
 wire [31:0] cpread,status,cause,epc,badvaddr;wire irq_pending;
 cp0 system_control(.clk(clk),.rst(rst),.read_addr(rd),.read_data(cpread),
  .write_valid(wb_valid&&wb_cpwrite&&!wb_fault&&!rst),.write_addr(wb_cpaddr),.write_data(wb_data),
  .exception_valid(exception_valid),.exception_code(wb_code),.exception_pc(wb_epc),
  .exception_bd(wb_bd),.exception_badvaddr(wb_bad),.eret(wb_valid&&wb_eret&&!wb_fault&&!rst),
  .hw_irq(hw_irq),.status(status),.cause(cause),.epc(epc),.badvaddr(badvaddr),.irq_pending(irq_pending));
 always @* begin
  write_reg=0;write_rd=rt;write_data=0;control_transfer=0;take_branch=0;transfer_target=pc8;
  illegal=0;is_load=0;is_store=0;cpwrite=0;is_eret=0;fault=0;fault_code=0;fault_bad=effective_addr;
  store_data=b<<{effective_addr[1:0],3'b0};store_strobe=0;
  case(op)
   0:begin
    write_reg=1;write_rd=rd;
    case(fn)
     0:begin write_data=b<<sa;if(rs!=0)illegal=1;end
     2:begin write_data=b>>sa;if(rs!=0)illegal=1;end
     3:begin write_data=$signed(b)>>>sa;if(rs!=0)illegal=1;end
     4:begin write_data=b<<a[4:0];if(sa!=0)illegal=1;end
     6:begin write_data=b>>a[4:0];if(sa!=0)illegal=1;end
     7:begin write_data=$signed(b)>>>a[4:0];if(sa!=0)illegal=1;end
     8:begin write_reg=0;control_transfer=1;transfer_target=a;if(rt!=0||rd!=0||sa!=0)illegal=1;end
     9:begin write_data=pc8;control_transfer=1;transfer_target=a;if(rt!=0||sa!=0)illegal=1;end
     6'h0c:begin fault=1;fault_code=8;end
     6'h0d:begin fault=1;fault_code=9;end
     6'h20,6'h21:begin write_data=a+b;if(sa!=0)illegal=1;if(fn==6'h20&&a[31]==b[31]&&write_data[31]!=a[31])begin fault=1;fault_code=12;end end
     6'h22,6'h23:begin write_data=a-b;if(sa!=0)illegal=1;if(fn==6'h22&&a[31]!=b[31]&&write_data[31]!=a[31])begin fault=1;fault_code=12;end end
     6'h24:begin write_data=a&b;if(sa!=0)illegal=1;end
     6'h25:begin write_data=a|b;if(sa!=0)illegal=1;end
     6'h26:begin write_data=a^b;if(sa!=0)illegal=1;end
     6'h27:begin write_data=~(a|b);if(sa!=0)illegal=1;end
     6'h2a:begin write_data={31'b0,$signed(a)<$signed(b)};if(sa!=0)illegal=1;end
     6'h2b:begin write_data={31'b0,a<b};if(sa!=0)illegal=1;end
     default:illegal=1;
    endcase
   end
   1:begin
    control_transfer=1;
    case(rt)
     0:take_branch=$signed(a)<0;
     1:take_branch=$signed(a)>=0;
     16:begin take_branch=$signed(a)<0;write_reg=1;write_rd=31;write_data=pc8;end
     17:begin take_branch=$signed(a)>=0;write_reg=1;write_rd=31;write_data=pc8;end
     default:illegal=1;
    endcase
    transfer_target=take_branch?pc4+(simm<<2):pc8;
   end
   2,3:begin control_transfer=1;transfer_target={pc4[31:28],ex_instr[25:0],2'b00};if(op==3)begin write_reg=1;write_rd=31;write_data=pc8;end end
   4,5,6,7:begin
    control_transfer=1;
    case(op)
     4:take_branch=a==b;
     5:take_branch=a!=b;
     6:begin take_branch=$signed(a)<=0;if(rt!=0)illegal=1;end
     7:begin take_branch=$signed(a)>0;if(rt!=0)illegal=1;end
    endcase
    transfer_target=take_branch?pc4+(simm<<2):pc8;
   end
   8,9:begin write_reg=1;write_data=a+simm;if(op==8&&a[31]==simm[31]&&write_data[31]!=a[31])begin fault=1;fault_code=12;end end
   10:begin write_reg=1;write_data={31'b0,$signed(a)<$signed(simm)};end
   11:begin write_reg=1;write_data={31'b0,a<simm};end
   12:begin write_reg=1;write_data=a&zimm;end
   13:begin write_reg=1;write_data=a|zimm;end
   14:begin write_reg=1;write_data=a^zimm;end
   15:begin write_reg=1;write_data={ex_instr[15:0],16'b0};if(rs!=0)illegal=1;end
   16:begin
    if(ex_instr==32'h42000018)is_eret=1;
    else if(rs==0&&ex_instr[10:0]==0)begin write_reg=1;write_data=cpread;end
    else if(rs==4&&ex_instr[10:0]==0)cpwrite=1;
    else illegal=1;
   end
   32,33,35,36,37:begin
    write_reg=1;is_load=1;
    if(((op==33||op==37)&&effective_addr[0])||(op==35&&effective_addr[1:0]!=0))begin fault=1;fault_code=4;end
   end
   40,41,43:begin
    is_store=1;
    case(op)
     40:store_strobe=4'b0001<<effective_addr[1:0];
     41:begin store_strobe=4'b0011<<effective_addr[1:0];if(effective_addr[0])begin fault=1;fault_code=5;end end
     43:begin store_strobe=15;if(effective_addr[1:0]!=0)begin fault=1;fault_code=5;end end
    endcase
   end
   default:illegal=1;
  endcase
  if(ex_bd&&(control_transfer||is_eret))illegal=1;
  if(illegal)begin fault=1;fault_code=10;end
  if(ex_pc[1:0]!=0)begin fault=1;fault_code=4;fault_bad=ex_pc;end
  // Synchronous faults win; defer IRQ until a non-delay instruction boundary.
  if(!fault&&irq_pending&&!ex_bd)begin fault=1;fault_code=0;end
  if(fault)begin write_reg=0;is_load=0;is_store=0;store_strobe=0;cpwrite=0;is_eret=0;control_transfer=0;end
 end
 wire mem_wait=mem_valid&&(mem_load||mem_store)&&!dmem_ready;
 wire id_cp=id_instr[31:26]==16;
 wire serial_active=(ex_valid&&ex_instr[31:26]==16)||(mem_valid&&mem_instr[31:26]==16)||(wb_valid&&wb_instr[31:26]==16);
 // Conservative source matching also stalls unused encoded fields; correctness
 // does not depend on optimizing these occasional extra bubbles.
 wire load_use=ex_valid&&is_load&&write_rd!=0&&id_valid&&(write_rd==id_instr[25:21]||write_rd==id_instr[20:16]);
 wire serial_stall=serial_active||(id_valid&&id_cp&&(ex_valid||mem_valid||wb_valid));
 wire front_stall=load_use||serial_stall;
 assign imem_addr=if_pc;
 assign dmem_valid=!rst&&mem_valid&&!mem_fault&&(mem_load||mem_store);
 assign dmem_write=mem_store;
 assign dmem_addr=mem_addr;assign dmem_wdata=mem_data;assign dmem_wstrb=dmem_valid&&mem_store?mem_strobe:4'b0;
 assign trace_valid=!rst&&wb_valid&&!wb_fault;
 assign trace_pc=wb_pc;assign trace_instr=wb_instr;
 assign trace_we=trace_valid&&wb_we&&wb_rd!=0;assign trace_rd=wb_rd;assign trace_wdata=wb_value;
 assign trace_mem_we=trace_valid?wb_strobe:4'b0;assign trace_mem_addr=wb_addr;assign trace_mem_wdata=wb_data;
 assign exception_valid=!rst&&wb_valid&&wb_fault;assign exception_code=wb_code;assign exception_epc=wb_epc;assign exception_bd=wb_bd;
 wire [31:0] lane=dmem_rdata>>{mem_addr[1:0],3'b0};reg [31:0] load_value;
 always @* begin
  case(mem_instr[31:26])
   32:load_value={{24{lane[7]}},lane[7:0]};33:load_value={{16{lane[15]}},lane[15:0]};
   36:load_value={24'b0,lane[7:0]};37:load_value={16'b0,lane[15:0]};default:load_value=dmem_rdata;
  endcase
 end
 always @(posedge clk)begin
  if(rst)begin
   if_pc<=RESET_PC;id_valid<=0;ex_valid<=0;mem_valid<=0;wb_valid<=0;trap_wait<=0;
   id_pc<=0;id_instr<=0;ex_pc<=0;ex_instr<=0;mem_pc<=0;mem_instr<=0;wb_pc<=0;wb_instr<=0;ex_bd<=0;ex_branch_pc<=0;
   mem_we<=0;mem_load<=0;mem_store<=0;mem_fault<=0;mem_bd<=0;mem_cpwrite<=0;mem_eret<=0;mem_rd<=0;mem_code<=0;mem_cpaddr<=0;mem_value<=0;mem_addr<=0;mem_data<=0;mem_epc<=0;mem_bad<=0;mem_strobe<=0;
   wb_we<=0;wb_fault<=0;wb_bd<=0;wb_cpwrite<=0;wb_eret<=0;wb_rd<=0;wb_code<=0;wb_cpaddr<=0;wb_value<=0;wb_addr<=0;wb_data<=0;wb_epc<=0;wb_bad<=0;wb_strobe<=0;
   cycle_count<=0;retired_count<=0;stall_count<=0;
   for(n=0;n<32;n=n+1)regs[n]<=0;
  end else begin
   cycle_count<=cycle_count+1;if(trace_valid)retired_count<=retired_count+1;
   if(mem_wait||front_stall||trap_wait)stall_count<=stall_count+1;
   if(trace_we)regs[wb_rd]<=wb_value;regs[0]<=0;
   // WB drains even while MEM waits; no repeated architectural retirement.
   wb_valid<=0;
   if(exception_valid||(wb_valid&&wb_eret))begin
    if_pc<=exception_valid?EXCEPTION_PC:epc;id_valid<=0;ex_valid<=0;mem_valid<=0;trap_wait<=0;
   end else if(!mem_wait)begin
    wb_valid<=mem_valid;wb_pc<=mem_pc;wb_instr<=mem_instr;wb_we<=mem_we;wb_rd<=mem_rd;
    wb_value<=mem_load?load_value:mem_value;wb_addr<=mem_addr;wb_data<=mem_data;wb_strobe<=mem_store?mem_strobe:4'b0;
    wb_fault<=mem_fault;wb_code<=mem_code;wb_epc<=mem_epc;wb_bd<=mem_bd;wb_bad<=mem_bad;wb_cpwrite<=mem_cpwrite;wb_cpaddr<=mem_cpaddr;wb_eret<=mem_eret;
    mem_valid<=ex_valid;mem_pc<=ex_pc;mem_instr<=ex_instr;mem_we<=write_reg;mem_rd<=write_rd;mem_value<=write_data;
    mem_load<=is_load;mem_store<=is_store;mem_addr<=effective_addr;mem_data<=cpwrite?b:store_data;mem_strobe<=store_strobe;
    mem_fault<=fault;mem_code<=fault_code;mem_epc<=ex_bd?ex_branch_pc:ex_pc;mem_bd<=ex_bd;mem_bad<=fault_bad;
    mem_cpwrite<=cpwrite;mem_cpaddr<=rd;mem_eret<=is_eret;
    ex_valid<=0;
    if(ex_valid&&fault)begin id_valid<=0;trap_wait<=1;end
    else if(!trap_wait)begin
     if(ex_valid&&control_transfer)begin
      ex_valid<=id_valid;ex_pc<=id_pc;ex_instr<=id_instr;ex_bd<=1;ex_branch_pc<=ex_pc;
      id_valid<=0;if_pc<=transfer_target;
     end else if(!front_stall)begin
      ex_valid<=id_valid;ex_pc<=id_pc;ex_instr<=id_instr;ex_bd<=0;
      id_valid<=1;id_pc<=if_pc;id_instr<=imem_rdata;if_pc<=if_pc+4;
     end
    end
   end
  end
 end
endmodule

rtl/core/single_cycle_cpu.v.text:
`timescale 1ns/1ps
// Single-cycle teaching reference. Combinational memories, little endian.
// ADD/ADDI/SUB wrap here; precise overflow exceptions belong to pipeline_cpu.
module single_cycle_cpu #(
    parameter RESET_PC = 32'hbfc00000
)(
    input wire clk, input wire rst,
    output wire [31:0] imem_addr, input wire [31:0] imem_rdata,
    output reg [31:0] dmem_addr, output reg [31:0] dmem_wdata,
    output reg [3:0] dmem_wstrb, input wire [31:0] dmem_rdata,
    output wire trace_valid, output wire [31:0] trace_pc,
    output wire [31:0] trace_instr, output wire trace_we,
    output wire [4:0] trace_rd, output wire [31:0] trace_wdata,
    output reg illegal
);
    reg [31:0] pc;
    reg [31:0] regs [0:31];
    // Record a redirect for every branch, including its untaken PC+8 path.
    reg delay_pending;
    reg [31:0] delay_target;
    wire [5:0] op = imem_rdata[31:26];
    wire [5:0] fn = imem_rdata[5:0];
    wire [4:0] rs = imem_rdata[25:21];
    wire [4:0] rt = imem_rdata[20:16];
    wire [4:0] rd = imem_rdata[15:11];
    wire [4:0] sa = imem_rdata[10:6];
    wire [31:0] a = rs == 0 ? 32'b0 : regs[rs];
    wire [31:0] b = rt == 0 ? 32'b0 : regs[rt];
    wire [31:0] simm = {{16{imem_rdata[15]}},imem_rdata[15:0]};
    wire [31:0] zimm = {16'b0,imem_rdata[15:0]};
    wire [31:0] pc4 = pc + 32'd4;
    wire [31:0] pc8 = pc + 32'd8;
    wire [31:0] effective_addr = a + simm;
    wire [31:0] load_lane = dmem_rdata >> {effective_addr[1:0],3'b0};
    reg write_reg, control_transfer, take_branch;
    reg [4:0] write_rd;
    reg [31:0] write_data, transfer_target;
    integer n;

    assign imem_addr = pc;
    assign trace_valid = !rst;
    assign trace_pc = pc;
    assign trace_instr = imem_rdata;
    assign trace_we = !rst && !illegal && write_reg && write_rd != 0;
    assign trace_rd = write_rd;
    assign trace_wdata = write_data;

    always @* begin
        write_reg = 0;
        write_rd = rt;
        write_data = 0;
        dmem_addr = effective_addr;
        dmem_wdata = b << {effective_addr[1:0],3'b0};
        dmem_wstrb = 0;
        control_transfer = 0;
        transfer_target = pc8;
        take_branch = 0;
        illegal = 0;
        case (op)
            6'h00: begin
                write_reg = 1;
                write_rd = rd;
                case(fn)
                    6'h00: begin write_data = b << sa; if(rs != 0) illegal=1; end
                    6'h02: begin write_data = b >> sa; if(rs != 0) illegal=1; end
                    6'h03: begin write_data = $signed(b) >>> sa; if(rs != 0) illegal=1; end
                    6'h04: begin write_data = b << a[4:0]; if(sa != 0) illegal=1; end
                    6'h06: begin write_data = b >> a[4:0]; if(sa != 0) illegal=1; end
                    6'h07: begin write_data = $signed(b) >>> a[4:0]; if(sa != 0) illegal=1; end
                    6'h08: begin
                        write_reg=0; control_transfer=1; transfer_target=a;
                        if(rt != 0 || rd != 0 || sa != 0 || a[1:0] != 0) illegal=1;
                    end
                    6'h09: begin
                        write_data=pc8; control_transfer=1; transfer_target=a;
                        if(rt != 0 || sa != 0 || a[1:0] != 0) illegal=1;
                    end
                    6'h20,6'h21: begin write_data=a+b; if(sa != 0) illegal=1; end
                    6'h22,6'h23: begin write_data=a-b; if(sa != 0) illegal=1; end
                    6'h24: begin write_data=a&b; if(sa != 0) illegal=1; end
                    6'h25: begin write_data=a|b; if(sa != 0) illegal=1; end
                    6'h26: begin write_data=a^b; if(sa != 0) illegal=1; end
                    6'h27: begin write_data=~(a|b); if(sa != 0) illegal=1; end
                    6'h2a: begin write_data={31'b0,$signed(a)<$signed(b)}; if(sa != 0) illegal=1; end
                    6'h2b: begin write_data={31'b0,a<b}; if(sa != 0) illegal=1; end
                    default: illegal=1;
                endcase
            end
            6'h01: begin
                control_transfer=1;
                case(rt)
                    5'h00: take_branch=$signed(a)<0;
                    5'h01: take_branch=$signed(a)>=0;
                    // REGIMM link variants write $31 independently of outcome.
                    5'h10: begin take_branch=$signed(a)<0; write_reg=1; write_rd=31; write_data=pc8; end
                    5'h11: begin take_branch=$signed(a)>=0; write_reg=1; write_rd=31; write_data=pc8; end
                    default: illegal=1;
                endcase
                transfer_target=take_branch ? pc4+(simm<<2) : pc8;
            end
            6'h02,6'h03: begin
                control_transfer=1;
                transfer_target={pc4[31:28],imem_rdata[25:0],2'b00};
                if(op==6'h03)begin write_reg=1;write_rd=31;write_data=pc8;end
            end
            6'h04,6'h05,6'h06,6'h07: begin
                control_transfer=1;
                case(op)
                    6'h04: take_branch=a==b;
                    6'h05: take_branch=a!=b;
                    6'h06: begin take_branch=$signed(a)<=0;if(rt!=0)illegal=1;end
                    6'h07: begin take_branch=$signed(a)>0;if(rt!=0)illegal=1;end
                endcase
                transfer_target=take_branch ? pc4+(simm<<2) : pc8;
            end
            6'h08,6'h09: begin write_reg=1;write_data=a+simm;end
            6'h0a: begin write_reg=1;write_data={31'b0,$signed(a)<$signed(simm)};end
            6'h0b: begin write_reg=1;write_data={31'b0,a<simm};end
            6'h0c: begin write_reg=1;write_data=a&zimm;end
            6'h0d: begin write_reg=1;write_data=a|zimm;end
            6'h0e: begin write_reg=1;write_data=a^zimm;end
            6'h0f: begin write_reg=1;write_data={imem_rdata[15:0],16'b0};if(rs!=0)illegal=1;end
            6'h20: begin write_reg=1;write_data={{24{load_lane[7]}},load_lane[7:0]};end
            6'h21: begin write_reg=1;write_data={{16{load_lane[15]}},load_lane[15:0]};if(effective_addr[0])illegal=1;end
            6'h23: begin write_reg=1;write_data=dmem_rdata;if(effective_addr[1:0]!=0)illegal=1;end
            6'h24: begin write_reg=1;write_data={24'b0,load_lane[7:0]};end
            6'h25: begin write_reg=1;write_data={16'b0,load_lane[15:0]};if(effective_addr[0])illegal=1;end
            6'h28: dmem_wstrb=4'b0001<<effective_addr[1:0];
            6'h29: begin dmem_wstrb=4'b0011<<effective_addr[1:0];if(effective_addr[0])illegal=1;end
            6'h2b: begin dmem_wstrb=4'b1111;if(effective_addr[1:0]!=0)illegal=1;end
            default: illegal=1;
        endcase
        // A control transfer in a delay slot is architecturally unpredictable.
        // This reference rejects it deterministically without replacing redirect.
        if(pc[1:0]!=0 || (delay_pending && control_transfer)) illegal=1;
        if(illegal || rst)begin
            write_reg=0;
            dmem_wstrb=0;
            control_transfer=0;
        end
        if(rst)illegal=0;
    end

    always @(posedge clk) begin
        if(rst)begin
            pc<=RESET_PC;
            delay_pending<=0;
            delay_target<=0;
            for(n=0;n<32;n=n+1)regs[n]<=0;
        end else begin
            pc<=delay_pending ? delay_target : pc4;
            delay_pending<=control_transfer;
            if(control_transfer)delay_target<=transfer_target;
            if(trace_we)regs[write_rd]<=write_data;
            regs[0]<=0;
        end
    end
endmodule

rtl/integration/cached_cpu.v.text:
`timescale 1ns/1ps
// Blocking CPU/cache composition. MMIO is a separate, uncached handshake port.
module cached_cpu #(
 parameter RESET_PC=32'hbfc00000, EXCEPTION_PC=32'hbfc00380,
 parameter integer SETS=16, WORDS_PER_LINE=4,
 parameter MMIO_BASE=32'hffff0000, MMIO_MASK=32'hffff0000
)(
 input wire clk,rst,
 output wire [31:0] imem_addr,input wire [31:0] imem_rdata,
 input wire [5:0] hw_irq,
 output wire mem_valid,mem_write,output wire [31:0] mem_addr,mem_wdata,
 output wire [3:0] mem_wstrb,input wire mem_ready,input wire [31:0] mem_rdata,
 output wire mmio_valid,mmio_write,output wire [31:0] mmio_addr,mmio_wdata,
 output wire [3:0] mmio_wstrb,input wire mmio_ready,input wire [31:0] mmio_rdata,
 output wire trace_valid,output wire [31:0] trace_pc,trace_instr,
 output wire trace_we,output wire [4:0] trace_rd,output wire [31:0] trace_wdata,
 output wire [3:0] trace_mem_we,output wire [31:0] trace_mem_addr,trace_mem_wdata,
 output wire exception_valid,output wire [4:0] exception_code,
 output wire [31:0] exception_epc,output wire exception_bd,
 output wire [31:0] cycle_count,retired_count,stall_count,
 output wire [31:0] hit_count,miss_count,writeback_count
);
 wire cpu_valid,cpu_write,cpu_ready,cache_ready;
 wire [31:0] cpu_addr,cpu_wdata,cpu_rdata,cache_rdata;
 wire [3:0] cpu_wstrb;
 wire uncached=(cpu_addr&MMIO_MASK)==(MMIO_BASE&MMIO_MASK);
 assign mmio_valid=cpu_valid&&uncached;
 assign mmio_write=cpu_write;
 assign mmio_addr=cpu_addr;
 assign mmio_wdata=cpu_wdata;
 assign mmio_wstrb=mmio_valid?cpu_wstrb:4'b0;
 assign cpu_ready=uncached?mmio_ready:cache_ready;
 assign cpu_rdata=uncached?mmio_rdata:cache_rdata;
 pipeline_cpu #(.RESET_PC(RESET_PC),.EXCEPTION_PC(EXCEPTION_PC)) core(
  .clk(clk),.rst(rst),.imem_addr(imem_addr),.imem_rdata(imem_rdata),.hw_irq(hw_irq),
  .dmem_valid(cpu_valid),.dmem_write(cpu_write),.dmem_addr(cpu_addr),.dmem_wdata(cpu_wdata),
  .dmem_wstrb(cpu_wstrb),.dmem_ready(cpu_ready),.dmem_rdata(cpu_rdata),
  .trace_valid(trace_valid),.trace_pc(trace_pc),.trace_instr(trace_instr),
  .trace_we(trace_we),.trace_rd(trace_rd),.trace_wdata(trace_wdata),
  .trace_mem_we(trace_mem_we),.trace_mem_addr(trace_mem_addr),.trace_mem_wdata(trace_mem_wdata),
  .exception_valid(exception_valid),.exception_code(exception_code),
  .exception_epc(exception_epc),.exception_bd(exception_bd),
  .cycle_count(cycle_count),.retired_count(retired_count),.stall_count(stall_count));
 data_cache #(.SETS(SETS),.WORDS_PER_LINE(WORDS_PER_LINE)) cache(
  .clk(clk),.rst(rst),.cpu_valid(cpu_valid&&!uncached),.cpu_write(cpu_write),
  .cpu_addr(cpu_addr),.cpu_wdata(cpu_wdata),.cpu_wstrb(cpu_wstrb),
  .cpu_ready(cache_ready),.cpu_rdata(cache_rdata),
  .mem_valid(mem_valid),.mem_write(mem_write),.mem_addr(mem_addr),.mem_wdata(mem_wdata),
  .mem_wstrb(mem_wstrb),.mem_ready(mem_ready),.mem_rdata(mem_rdata),
  .hit_count(hit_count),.miss_count(miss_count),.writeback_count(writeback_count));
endmodule

rtl/integration/lab1_num_led.v.text:
`timescale 1ns/1ps
// Course lab1 port-compatible implementation. rst is active LOW; outputs
// are active HIGH in abcdefg order, with two groups of four digits.
module lab1_num_led #(parameter COUNTER_WIDTH=20)(
 input wire rst,clk,
 output wire [6:0] digital_num0,digital_num1,
 output wire [7:0] digital_cs,
 input wire [7:0] switch,input wire center_btn_key
);
 reg meta,sync,stable;
 reg [COUNTER_WIDTH-1:0] debounce;
 reg [31:0] num_led_value;
 reg [1:0] write_byte_index;
 always @(posedge clk) begin
  if(!rst)begin
   meta<=0;sync<=0;stable<=0;debounce<=0;
   num_led_value<=0;write_byte_index<=0;
  end else begin
   meta<=center_btn_key;sync<=meta;
   if(sync==stable)debounce<=0;
   else if(debounce[COUNTER_WIDTH-1])begin
    stable<=sync;debounce<=0;
    if(sync)begin
     num_led_value[8*write_byte_index+:8]<=switch;
     write_byte_index<=write_byte_index+1'b1;
    end
   end else debounce<=debounce+1'b1;
  end
 end
 lab1_hex_display #(.COUNTER_WIDTH(COUNTER_WIDTH)) display(
  .clk(clk),.rstn(rst),.value(num_led_value),
  .digital_num0(digital_num0),.digital_num1(digital_num1),.digital_cs(digital_cs));
endmodule

// Also plugs into the original num_led display placeholder region via the
// local-only overlay generated by run_course_basics.py. No teacher RTL copied.
module lab1_hex_display #(parameter COUNTER_WIDTH=20)(
 input wire clk,rstn,input wire [31:0] value,
 output wire [6:0] digital_num0,digital_num1,output wire [7:0] digital_cs
);
 reg [COUNTER_WIDTH-1:0] scan_count;
 wire [1:0] phase=scan_count[COUNTER_WIDTH-1:COUNTER_WIDTH-2];
 function [6:0] encode(input [3:0] nibble);
  begin
   case(nibble)
    4'h0:encode=7'b1111110;4'h1:encode=7'b0110000;
    4'h2:encode=7'b1101101;4'h3:encode=7'b1111001;
    4'h4:encode=7'b0110011;4'h5:encode=7'b1011011;
    4'h6:encode=7'b1011111;4'h7:encode=7'b1110000;
    4'h8:encode=7'b1111111;4'h9:encode=7'b1111011;
    4'ha:encode=7'b1110111;4'hb:encode=7'b0011111;
    4'hc:encode=7'b1001110;4'hd:encode=7'b0111101;
    4'he:encode=7'b1001111;4'hf:encode=7'b1000111;
   endcase
  end
 endfunction
 always @(posedge clk)if(!rstn)scan_count<=0;else scan_count<=scan_count+1'b1;
 // Decode selection and data from the same phase, avoiding one-cycle ghosting
 // in the original independently registered scan/segment skeleton.
 assign digital_cs=rstn ? (8'h11<<phase) : 8'b0;
 assign digital_num0=rstn ? encode(value[4*phase+:4]) : 7'b0;
 assign digital_num1=rstn ? encode(value[16+4*phase+:4]) : 7'b0;
endmodule

rtl/integration/lab3_mycpu.v.text:
`timescale 1ns/1ps
// Drop-in missing mycpu for lab3/single_cycle. Course address layout and
// active-low reset retained. The course bus supports aligned WORD stores only.
module mycpu(
 input wire rstn,clk,
 output wire [31:0] inst_rom_addr,input wire [31:0] inst_rom_rdata,
 output wire [31:0] data_ram_addr,data_ram_wdata,
 output wire data_ram_wen,input wire [31:0] data_ram_rdata
);
 wire [3:0] wstrb;
 wire illegal;
 single_cycle_cpu #(.RESET_PC(32'hbfc00000)) core(
  .clk(clk),.rst(~rstn),.imem_addr(inst_rom_addr),.imem_rdata(inst_rom_rdata),
  .dmem_addr(data_ram_addr),.dmem_wdata(data_ram_wdata),.dmem_wstrb(wstrb),
  .dmem_rdata(data_ram_rdata),.trace_valid(),.trace_pc(),.trace_instr(),
  .trace_we(),.trace_rd(),.trace_wdata(),.illegal(illegal));
 assign data_ram_wen=rstn && (wstrb==4'b1111);
 // Byte/halfword stores cannot be represented by the original single-bit WE.
 // They are deliberately not converted to destructive full-word stores.
endmodule

rtl/integration/teach_mycpu_top.v.text:
`timescale 1ns/1ps
// Lab simulation compatibility adapter; see docs/teach-soc.md for clock limits.
// SRAM/bridge/confreg sample clk rising edges; CPU advances on falling edges.
// Do not include this inverted-clock adapter in the independently timed board SoC.
module mycpu_top(
 input wire clk, resetn,
 input wire [5:0] \int ,
 output wire inst_sram_en,
 output wire [3:0] inst_sram_wen,
 output wire [31:0] inst_sram_addr, inst_sram_wdata,
 input wire [31:0] inst_sram_rdata,
 output wire data_sram_en,
 output wire [3:0] data_sram_wen,
 output wire [31:0] data_sram_addr, data_sram_wdata,
 input wire [31:0] data_sram_rdata,
 output wire [31:0] debug_wb_pc,
 output wire [3:0] debug_wb_rf_wen,
 output wire [4:0] debug_wb_rf_wnum,
 output wire [31:0] debug_wb_rf_wdata
);
 wire core_clk = ~clk;
 wire [31:0] imem_addr, dmem_addr;
 wire dmem_valid, dmem_write;
 wire [3:0] dmem_wstrb;
 wire trace_valid, trace_we;
 wire [31:0] trace_instr;
 wire [3:0] trace_mem_we;
 wire [31:0] trace_mem_addr, trace_mem_wdata;
 wire exception_valid, exception_bd;
 wire [4:0] exception_code;
 wire [31:0] exception_epc, cycle_count, retired_count, stall_count;

 assign inst_sram_en = resetn;
 assign inst_sram_wen = 4'b0;
 assign inst_sram_wdata = 32'b0;
 assign inst_sram_addr = {3'b0,imem_addr[28:0]};
 assign data_sram_en = resetn && dmem_valid;
 assign data_sram_wen = (data_sram_en && dmem_write) ? dmem_wstrb : 4'b0;
 assign data_sram_addr = {3'b0,dmem_addr[28:0]};
 assign debug_wb_rf_wen = {4{resetn && trace_valid && trace_we}};

 pipeline_cpu core(
  .clk(core_clk), .rst(~resetn), .hw_irq(\int ),
  .imem_addr(imem_addr), .imem_rdata(inst_sram_rdata),
  .dmem_valid(dmem_valid), .dmem_write(dmem_write), .dmem_addr(dmem_addr),
  .dmem_wdata(data_sram_wdata), .dmem_wstrb(dmem_wstrb),
  .dmem_ready(resetn), .dmem_rdata(data_sram_rdata),
  .trace_valid(trace_valid), .trace_pc(debug_wb_pc), .trace_instr(trace_instr),
  .trace_we(trace_we), .trace_rd(debug_wb_rf_wnum), .trace_wdata(debug_wb_rf_wdata),
  .trace_mem_we(trace_mem_we), .trace_mem_addr(trace_mem_addr), .trace_mem_wdata(trace_mem_wdata),
  .exception_valid(exception_valid), .exception_code(exception_code),
  .exception_epc(exception_epc), .exception_bd(exception_bd),
  .cycle_count(cycle_count), .retired_count(retired_count), .stall_count(stall_count)
 );
endmodule

rtl/peripherals/seven_segment.v.text:
`timescale 1ns/1ps

module seven_segment #(
    parameter integer CLOCK_HZ = 100000000,
    parameter integer SCAN_HZ = 1000
) (
    input  wire        clk,
    input  wire        rst,
    input  wire [31:0] value,
    output reg  [7:0]  digit_n,
    output reg  [7:0]  segment_n
);
    localparam integer CLKS_PER_SCAN = (SCAN_HZ > 0) ? (CLOCK_HZ / SCAN_HZ) : 0;

    integer   scan_count;
    reg [2:0] digit_index;
    reg [3:0] hex_digit;

    generate
        if ((CLOCK_HZ <= 0) || (SCAN_HZ <= 0) || (CLKS_PER_SCAN < 1)) begin : invalid_parameters
            initial begin
                $error("seven_segment requires positive rates and CLOCK_HZ/SCAN_HZ >= 1");
                $finish;
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            scan_count  <= 0;
            digit_index <= 3'd0;
        end else if (scan_count == CLKS_PER_SCAN - 1) begin
            scan_count  <= 0;
            digit_index <= digit_index + 1'b1;
        end else begin
            scan_count <= scan_count + 1;
        end
    end

    always @* begin
        digit_n = ~(8'b00000001 << digit_index);
        hex_digit = value >> (digit_index * 4);
        case (hex_digit)
            4'h0: segment_n = 8'b11000000;
            4'h1: segment_n = 8'b11111001;
            4'h2: segment_n = 8'b10100100;
            4'h3: segment_n = 8'b10110000;
            4'h4: segment_n = 8'b10011001;
            4'h5: segment_n = 8'b10010010;
            4'h6: segment_n = 8'b10000010;
            4'h7: segment_n = 8'b11111000;
            4'h8: segment_n = 8'b10000000;
            4'h9: segment_n = 8'b10010000;
            4'hA: segment_n = 8'b10001000;
            4'hB: segment_n = 8'b10000011;
            4'hC: segment_n = 8'b11000110;
            4'hD: segment_n = 8'b10100001;
            4'hE: segment_n = 8'b10000110;
            default: segment_n = 8'b10001110;
        endcase
    end
endmodule

rtl/peripherals/uart_control.v.text:
`timescale 1ns/1ps
// Reusable UART light controller and atomic telemetry transport, 8N1.
module uart_control #(parameter integer CLOCK_HZ=10000000, BAUD=115200)(
 input wire clk,rst,rx,
 input wire [287:0] telemetry,
 output wire tx,
 output reg led_override,
 output reg [7:0] led_value,
 output reg cpu_reset,
 output wire beep,
 output reg [31:0] rx_errors
);
 wire received,frame_error,tx_ready;
 wire [7:0] rx_data;
 reg [319:0] snapshot;
 reg [5:0] bytes_left;
 reg [31:0] beep_left;
 uart_rx #(.CLOCK_HZ(CLOCK_HZ),.BAUD(BAUD)) receiver(
 .clk(clk),.rst(rst),.rx(rx),.rx_valid(received),.rx_data(rx_data),.frame_error(frame_error));
 uart_tx #(.CLOCK_HZ(CLOCK_HZ),.BAUD(BAUD)) transmitter(
 .clk(clk),.rst(rst),.tx_valid(bytes_left!=0),.tx_data(snapshot[7:0]),.tx_ready(tx_ready),.tx(tx));
 assign beep = beep_left != 0;
 always @(posedge clk) begin
  if(rst) begin
   snapshot<=0;bytes_left<=0;beep_left<=0;led_override<=0;led_value<=0;cpu_reset<=0;rx_errors<=0;
  end else begin
   cpu_reset<=0;
   if(beep_left!=0) beep_left<=beep_left-1;
   if(frame_error) rx_errors<=rx_errors+1;
   if(bytes_left!=0 && tx_ready) begin snapshot<=snapshot>>8;bytes_left<=bytes_left-1;end
   if(received) case(rx_data)
    8'h3f: if(bytes_left==0) begin snapshot<={telemetry,32'h5550434d};bytes_left<=40;end
    8'h30: begin led_override<=1;led_value<=0;end
    8'h31: begin led_override<=1;led_value<=8'hff;end
    8'h61: led_override<=0;
    8'h62: beep_left<=CLOCK_HZ/2;
    8'h72: cpu_reset<=1;
    default: begin end
   endcase
  end
 end
endmodule

rtl/peripherals/uart_rx.v.text:
`timescale 1ns/1ps

module uart_rx #(
    parameter integer CLOCK_HZ = 100000000,
    parameter integer BAUD = 115200
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       rx,
    output reg        rx_valid,
    output reg  [7:0] rx_data,
    output reg        frame_error
);
    localparam integer CLKS_PER_BIT = (BAUD > 0) ? (CLOCK_HZ / BAUD) : 0;
    localparam integer HALF_CLKS = CLKS_PER_BIT / 2;
    localparam [1:0] IDLE  = 2'd0;
    localparam [1:0] START = 2'd1;
    localparam [1:0] DATA  = 2'd2;
    localparam [1:0] STOP  = 2'd3;

    reg       rx_meta;
    reg       rx_sync;
    reg [1:0] state;
    reg [2:0] bit_index;
    integer   clock_count;

    generate
        if ((CLOCK_HZ <= 0) || (BAUD <= 0) || (CLKS_PER_BIT < 4)) begin : invalid_parameters
            initial begin
                $error("uart_rx requires positive rates and CLOCK_HZ/BAUD >= 4");
                $finish;
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            rx_meta <= 1'b1;
            rx_sync <= 1'b1;
        end else begin
            rx_meta <= rx;
            rx_sync <= rx_meta;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            rx_valid    <= 1'b0;
            rx_data     <= 8'h00;
            frame_error <= 1'b0;
            state       <= IDLE;
            bit_index   <= 3'd0;
            clock_count <= 0;
        end else begin
            rx_valid    <= 1'b0;
            frame_error <= 1'b0;

            case (state)
                IDLE: begin
                    clock_count <= 0;
                    bit_index   <= 3'd0;
                    if (!rx_sync) begin
                        state       <= START;
                        clock_count <= HALF_CLKS - 1;
                    end
                end

                START: begin
                    if (clock_count == 0) begin
                        if (!rx_sync) begin
                            state       <= DATA;
                            clock_count <= CLKS_PER_BIT - 1;
                            bit_index   <= 3'd0;
                        end else begin
                            state <= IDLE;
                        end
                    end else begin
                        clock_count <= clock_count - 1;
                    end
                end

                DATA: begin
                    if (clock_count == 0) begin
                        rx_data[bit_index] <= rx_sync;
                        clock_count       <= CLKS_PER_BIT - 1;
                        if (bit_index == 3'd7) begin
                            state <= STOP;
                        end else begin
                            bit_index <= bit_index + 1'b1;
                        end
                    end else begin
                        clock_count <= clock_count - 1;
                    end
                end

                STOP: begin
                    if (clock_count == 0) begin
                        if (rx_sync)
                            rx_valid <= 1'b1;
                        else
                            frame_error <= 1'b1;
                        state       <= IDLE;
                        clock_count <= 0;
                    end else begin
                        clock_count <= clock_count - 1;
                    end
                end

                default: begin
                    state       <= IDLE;
                    clock_count <= 0;
                end
            endcase
        end
    end
endmodule

rtl/peripherals/uart_tx.v.text:
`timescale 1ns/1ps

module uart_tx #(
    parameter integer CLOCK_HZ = 100000000,
    parameter integer BAUD = 115200
) (
    input  wire       clk,
    input  wire       rst,
    input  wire       tx_valid,
    input  wire [7:0] tx_data,
    output wire       tx_ready,
    output wire       tx
);
    localparam integer CLKS_PER_BIT = (BAUD > 0) ? (CLOCK_HZ / BAUD) : 0;

    reg        busy;
    reg [9:0]  frame;
    reg [3:0]  bit_index;
    integer    clock_count;

    assign tx_ready = ~busy;
    assign tx = busy ? frame[bit_index] : 1'b1;

    generate
        if ((CLOCK_HZ <= 0) || (BAUD <= 0) || (CLKS_PER_BIT < 4)) begin : invalid_parameters
            initial begin
                $error("uart_tx requires positive rates and CLOCK_HZ/BAUD >= 4");
                $finish;
            end
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            busy        <= 1'b0;
            frame       <= 10'h3ff;
            bit_index   <= 4'd0;
            clock_count <= 0;
        end else if (!busy) begin
            clock_count <= 0;
            bit_index   <= 4'd0;
            if (tx_valid) begin
                frame <= {1'b1, tx_data, 1'b0};
                busy  <= 1'b1;
            end
        end else if (clock_count == CLKS_PER_BIT - 1) begin
            clock_count <= 0;
            if (bit_index == 4'd9) begin
                busy      <= 1'b0;
                bit_index <= 4'd0;
            end else begin
                bit_index <= bit_index + 1'b1;
            end
        end else begin
            clock_count <= clock_count + 1;
        end
    end
endmodule

rtl/soc/ees338_top.v.text:
`timescale 1ns/1ps
module ees338_top(input wire clk100,reset_n,uart_rx,
 input wire [7:0] switches,
 output wire uart_tx,output wire [7:0] led,digit,segment0,segment1,
 output wire buzzer_out);
 reg [2:0] divider=0;
 reg divided_clock=0;
 always @(posedge clk100) begin
  if(divider==4)begin divider<=0;divided_clock<=~divided_clock;end
  else divider<=divider+1'b1;
 end
 wire clk;
 BUFG clock_buffer(.I(divided_clock),.O(clk));
 (* ASYNC_REG="TRUE" *) reg [2:0] reset_sync=0;
 always @(posedge clk or negedge reset_n)
  if(!reset_n)reset_sync<=0;else reset_sync<={reset_sync[1:0],1'b1};
 (* ASYNC_REG="TRUE" *) reg [7:0] switch_meta=0,switch_sync=0;
 always @(posedge clk)begin switch_meta<=switches;switch_sync<=switch_meta;end
 wire [7:0] dn,sn;
 lab_soc soc(.clk(clk),.rst(!reset_sync[2]),.uart_rx_pin(uart_rx),.switches(switch_sync),
 .uart_tx_pin(uart_tx),.led(led),.digit_n(dn),.segment_n(sn),.buzzer_pin(buzzer_out),
 .debug_pc(),.debug_result(),.debug_stores(),.debug_done());
 assign digit=~dn;
 assign segment0=~sn;
 assign segment1=~sn;
endmodule

rtl/soc/lab_soc.v.text:
`timescale 1ns/1ps
module lab_soc #(parameter integer CLOCK_HZ=10000000, BAUD=115200,
 parameter ROM_FILE="board_rom.hex")(
 input wire clk,rst,uart_rx_pin,
 input wire [7:0] switches,
 output wire uart_tx_pin,
 output wire [7:0] led,digit_n,segment_n,
 output wire buzzer_pin,
 output wire [31:0] debug_pc,debug_result,debug_stores,
 output wire debug_done
);
 reg [31:0] rom[0:1023];
 (* ram_style="distributed" *) reg [7:0] ram0[0:1023];
 (* ram_style="distributed" *) reg [7:0] ram1[0:1023];
 (* ram_style="distributed" *) reg [7:0] ram2[0:1023];
 (* ram_style="distributed" *) reg [7:0] ram3[0:1023];
 reg [31:0] last_fibonacci;
 initial $readmemh(ROM_FILE,rom);
 wire [31:0] ia,da,dw,dr,instruction;
 wire [3:0] strb;
 wire illegal,trace_valid,trace_we;
 wire [4:0] trace_rd;
 wire [31:0] trace_data,trace_instr,trace_pc;
 wire monitor_reset,override_led,beep;
 wire [7:0] override_value;
 wire core_rst=rst|monitor_reset;
 reg [31:0] cycles,retired,stores,errors,display_value,buzzer_value;
 reg [7:0] led_value;
 reg done;
 wire [31:0] rx_errors;
 wire mmio=da[31:8]==24'h1f0000;
 wire ram_select=da[31:12]==20'h10010;
 reg [31:0] mmio_read;
 assign instruction=(ia[31:12]==20'h00400)?rom[ia[11:2]]:32'hffffffff;
 assign dr=mmio?mmio_read:(ram_select?{ram3[da[11:2]],ram2[da[11:2]],ram1[da[11:2]],ram0[da[11:2]]}:32'h0);
 single_cycle_cpu #(.RESET_PC(32'h00400000)) cpu(
 .clk(clk),.rst(core_rst),.imem_addr(ia),.imem_rdata(instruction),
 .dmem_addr(da),.dmem_wdata(dw),.dmem_wstrb(strb),.dmem_rdata(dr),
 .trace_valid(trace_valid),.trace_pc(trace_pc),.trace_instr(trace_instr),.trace_we(trace_we),
 .trace_rd(trace_rd),.trace_wdata(trace_data),.illegal(illegal));
 always @* begin
  case(da[7:2])
   0:mmio_read={24'h0,switches};
   1:mmio_read={24'h0,led_value};
   2:mmio_read=display_value;
   3:mmio_read=buzzer_value;
   7:mmio_read=cycles;
   8:mmio_read={31'h0,done};
   default:mmio_read=0;
  endcase
 end
 integer k;
 always @(posedge clk) begin
  if(!core_rst && ram_select) begin
   if(strb[0])ram0[da[11:2]]<=dw[7:0];
   if(strb[1])ram1[da[11:2]]<=dw[15:8];
   if(strb[2])ram2[da[11:2]]<=dw[23:16];
   if(strb[3])ram3[da[11:2]]<=dw[31:24];
  end
 end
 always @(posedge clk) begin
  if(core_rst) begin
   cycles<=0;retired<=0;stores<=0;errors<=0;display_value<=0;led_value<=0;buzzer_value<=0;done<=0;last_fibonacci<=0;
   // RAM is intentionally not reset; software initializes its used locations.
  end else begin
   cycles<=cycles+1;
   if(trace_valid)retired<=retired+1;
   if(illegal)errors<=errors+1;
   if(|strb) begin
    if(ram_select) begin
     stores<=stores+1;
     if(da[11:2]==11)for(k=0;k<4;k=k+1)if(strb[k])last_fibonacci[8*k+:8]<=dw[8*k+:8];
    end
    if(mmio) case(da[7:2])
     1:if(strb[0])led_value<=dw[7:0];
     2:for(k=0;k<4;k=k+1)if(strb[k])display_value[8*k+:8]<=dw[8*k+:8];
     3:for(k=0;k<4;k=k+1)if(strb[k])buzzer_value[8*k+:8]<=dw[8*k+:8];
     8:if(strb[0])done<=dw[0];
     default:begin end
    endcase
   end
  end
 end
 assign debug_pc=ia;
 assign debug_result=done?last_fibonacci:0;
 assign debug_stores=stores;
 assign debug_done=done;
 assign led=override_led?override_value:led_value;
 wire [31:0] status={30'h0,(errors!=0),done};
 wire [31:0] gpio={16'h0,switches,led};
 uart_control #(.CLOCK_HZ(CLOCK_HZ),.BAUD(BAUD)) control(
 .clk(clk),.rst(rst),.rx(uart_rx_pin),.telemetry({errors+rx_errors,retired,gpio,display_value,stores,cycles,debug_result,ia,status}),
 .tx(uart_tx_pin),.led_override(override_led),.led_value(override_value),.cpu_reset(monitor_reset),.beep(beep),.rx_errors(rx_errors));
 seven_segment #(.CLOCK_HZ(CLOCK_HZ),.SCAN_HZ(1000)) display(
 .clk(clk),.rst(rst),.value(display_value),.digit_n(digit_n),.segment_n(segment_n));
 buzzer #(.CLOCK_HZ(CLOCK_HZ)) sound(
 .clk(clk),.rst(rst),.enable(beep|buzzer_value[0]),.frequency_hz(16'd2000),.wave(buzzer_pin));
endmodule

