"""Independent instruction interpreter and deterministic generated test program."""
import random
def I(op,rs,rt,imm):return (op<<26)|(rs<<21)|(rt<<16)|(imm&65535)
def R(rs,rt,rd,fn,sa=0):return rs<<21|rt<<16|rd<<11|sa<<6|fn
def signed(v):return v if v<0x80000000 else v-0x100000000
def generate(path,mutate=False):
    rng=random.Random(0x5A17)
    code=[I(9,0,1,7),I(9,1,2,-3),R(2,2,3,33),I(43,0,3,0),I(35,0,4,0),R(4,4,5,33),I(43,0,5,4),I(4,5,5,2),I(9,5,6,1),I(43,0,1,100),I(5,5,6,2),I(9,6,7,1),I(43,0,1,100)]
    for n in range(220):
        a,b,d=[rng.randrange(1,16) for _ in range(3)]
        if n%11==0:code += [I(43,0,a,(n%32)*4),I(35,0,b,(n%32)*4),R(b,b,d,33)]
        elif n%3==0:code.append(R(a,b,d,rng.choice([33,35,36,37,38,39,42,43])))
        elif n%3==1:code.append(I(rng.choice([9,10,11,12,13,14]),a,d,rng.randrange(-32768,32768)))
        else:code.append(R(0,b,d,rng.choice([0,2,3]),rng.randrange(32)))
    # Lane stores, signed/unsigned loads, variable shifts and zero writes.
    code += [I(15,0,16,0x80ff),I(13,16,16,0x81fe),I(43,0,16,160)]
    for off in range(4):code += [I(32,0,17,160+off),I(36,0,18,160+off),I(40,0,16,180+off)]
    for off in (0,2):code += [I(33,0,17,160+off),I(37,0,18,160+off),I(41,0,16,184+off)]
    for shift in range(32):
        code += [I(9,0,17,shift)]+[R(17,16,18,fn) for fn in (4,6,7)]
    code += [R(18,18,0,33),I(9,0,19,-1)]
    for op in (4,5,6,7,1):
        for positive in (False,True):
            code += [I(9,0,19,1 if positive else -1),I(op,19,19 if op in (4,5) else 0,2),I(9,0,20,12),I(9,0,20,13)]
    # REGIMM link both outcomes, JAL and JALR (rs==rd), backward loop.
    for rt in (1,16,17):
        for val in (-1,1):code += [I(9,0,19,val),I(1,19,rt,2),I(9,31,20,1),I(9,0,20,13)]
    base=len(code)*4;code += [(3<<26)|((base+12)//4),I(9,31,20,0),I(9,0,20,99)]
    base=len(code)*4;code += [I(9,0,21,base+16),R(21,0,21,9),I(9,21,20,0),I(9,0,20,99)]
    code += [I(9,0,22,3),I(9,22,22,-1),I(7,22,0,-2),I(9,20,20,1),I(43,0,7,252)]
    regs=[0]*32;mem=[0]*256;pc=0;pending=None;expected=[]
    while pc//4<len(code):
        ins=code[pc//4];op=ins>>26;rs=(ins>>21)&31;rt=(ins>>16)&31;rd=(ins>>11)&31;sa=(ins>>6)&31;fn=ins&63
        a,b=regs[rs],regs[rt];imm=ins&65535;si=imm if imm<32768 else imm-65536;dest=rt;we=0;val=0;mw=0;ma=0;md=0;target=None
        if op==0 and fn in (8,9):
            target=a;dest=rd;we=int(fn==9);val=pc+8
        elif op==0:
            dest=rd;we=1
            val={0:lambda:b<<sa,2:lambda:b>>sa,3:lambda:signed(b)>>sa,4:lambda:b<<(a&31),6:lambda:b>>(a&31),7:lambda:signed(b)>>(a&31),33:lambda:a+b,35:lambda:a-b,36:lambda:a&b,37:lambda:a|b,38:lambda:a^b,39:lambda:~(a|b),42:lambda:int(signed(a)<signed(b)),43:lambda:int(a<b)}[fn]()
        elif op in (1,4,5,6,7):
            take={1:lambda:signed(a)<0 if rt in (0,16) else signed(a)>=0,4:lambda:a==b,5:lambda:a!=b,6:lambda:signed(a)<=0,7:lambda:signed(a)>0}[op]()
            target=pc+4+si*4 if take else pc+8
            if op==1 and rt in (16,17):dest=31;we=1;val=pc+8
        elif op in (2,3):target=((pc+4)&0xf0000000)|((ins&0x3ffffff)<<2);we=int(op==3);dest=31;val=pc+8
        elif op in (40,41,43):
            ma=(a+si)&0xffffffff;offset=ma&3;size={40:1,41:2,43:4}[op];md=(b<<(offset*8))&0xffffffff;mw=((1<<size)-1)<<offset
            for lane in range(4):
                if mw&(1<<lane):mem[ma//4]=(mem[ma//4]&~(255<<(8*lane)))|(md&(255<<(8*lane)))
        elif op in (32,33,35,36,37):
            addr=(a+si)&0xffffffff;size={32:1,33:2,35:4,36:1,37:2}[op];bits=size*8
            val=(mem[addr//4]>>((addr&3)*8))&((1<<bits)-1);we=1
            if op in (32,33) and val&(1<<(bits-1)):val-=1<<bits
        else:
            we=1;val={9:lambda:a+si,10:lambda:int(signed(a)<si),11:lambda:int(a<(si&0xffffffff)),12:lambda:a&imm,13:lambda:a|imm,14:lambda:a^imm,15:lambda:imm<<16}[op]()
        val &= 0xffffffff;we=int(bool(we and dest));
        if we:regs[dest]=val
        expected.append((pc,ins,we,dest if we else 0,val if we else 0,mw,ma,md))
        pc,pending=(pending if pending is not None else pc+4),target
    if mutate:
        row=list(expected[0]);row[4]^=1;expected[0]=tuple(row)
    (path/'pipeline_program.hex').write_text('\n'.join(f'{v:08x}' for v in code)+'\n')
    (path/'pipeline_expected.txt').write_text(str(len(expected))+'\n'+'\n'.join(' '.join(f'{v:x}' for v in row) for row in expected)+'\n')

tests/tb_cache.sv.text:
`timescale 1ns/1ps

module tb_cache;
`ifdef CACHE_SMALL_VARIANT
    localparam integer SETS = 4;
    localparam integer WORDS_PER_LINE = 2;
`else
    localparam integer SETS = 16;
    localparam integer WORDS_PER_LINE = 4;
`endif
    localparam integer MEM_WORDS = 16384;

    reg clk;
    reg rst;

    reg         cpu_valid;
    reg         cpu_write;
    reg  [31:0] cpu_addr;
    reg  [31:0] cpu_wdata;
    reg  [3:0]  cpu_wstrb;
    wire        cpu_ready;
    wire [31:0] cpu_rdata;

    wire        mem_valid;
    wire        mem_write;
    wire [31:0] mem_addr;
    wire [31:0] mem_wdata;
    wire [3:0]  mem_wstrb;
    wire        mem_ready;
    wire [31:0] mem_rdata;

    wire [31:0] hit_count;
    wire [31:0] miss_count;
    wire [31:0] writeback_count;

    reg [31:0] backing_mem [0:MEM_WORDS-1];
    reg [31:0] reference_mem [0:MEM_WORDS-1];

    reg         memory_active;
    reg         held_mem_write;
    reg  [31:0] held_mem_addr;
    reg  [31:0] held_mem_wdata;
    reg  [3:0]  held_mem_wstrb;
    integer     memory_delay;
    integer     forced_delay;
    reg  [31:0] random_state;
    integer     memory_reads;
    integer     memory_writes;
    reg  [7:0]  random_delays_seen;
    integer     cpu_completions;
    integer     completions_since_reset;

    reg         cpu_stalled;
    reg         held_cpu_write;
    reg  [31:0] held_cpu_addr;
    reg  [31:0] held_cpu_wdata;
    reg  [3:0]  held_cpu_wstrb;

    integer i;
    integer random_iteration;
    integer completion_snapshot;
    integer backing_snapshot;
    integer memory_write_snapshot;
    reg [31:0] addr_a;
    reg [31:0] addr_b;
    reg [31:0] addr_c;
    reg [31:0] addr_d;
    reg [31:0] addr_e;
    reg [31:0] addr_f;
    reg [31:0] random_addr;
    reg [31:0] read_value;
    reg [31:0] write_value;
    reg [3:0]  write_mask;

    data_cache #(
        .SETS(SETS),
        .WORDS_PER_LINE(WORDS_PER_LINE)
    ) dut (
        .clk(clk),
        .rst(rst),
        .cpu_valid(cpu_valid),
        .cpu_write(cpu_write),
        .cpu_addr(cpu_addr),
        .cpu_wdata(cpu_wdata),
        .cpu_wstrb(cpu_wstrb),
        .cpu_ready(cpu_ready),
        .cpu_rdata(cpu_rdata),
        .mem_valid(mem_valid),
        .mem_write(mem_write),
        .mem_addr(mem_addr),
        .mem_wdata(mem_wdata),
        .mem_wstrb(mem_wstrb),
        .mem_ready(mem_ready),
        .mem_rdata(mem_rdata),
        .hit_count(hit_count),
        .miss_count(miss_count),
        .writeback_count(writeback_count)
    );

    function [31:0] make_addr;
        input integer tag_number;
        input integer set_number;
        input integer word_number;
        begin
            make_addr = (((tag_number * SETS) + set_number) * WORDS_PER_LINE
                         + word_number) * 4;
        end
    endfunction

    function integer memory_index;
        input [31:0] address;
        begin
            memory_index = (address >> 2) % MEM_WORDS;
        end
    endfunction

    function [31:0] merge_bytes;
        input [31:0] previous;
        input [31:0] replacement;
        input [3:0] strobes;
        integer lane;
        begin
            merge_bytes = previous;
            for (lane = 0; lane < 4; lane = lane + 1) begin
                if (strobes[lane])
                    merge_bytes[lane*8 +: 8] = replacement[lane*8 +: 8];
            end
        end
    endfunction

    task automatic check;
        input condition;
        input [8*120-1:0] message;
        begin
            if (!condition) begin
                $display("TB_CACHE_FAIL: %0s at time %0t", message, $time);
                $fatal(1);
            end
        end
    endtask

    task automatic apply_reset;
        begin
            @(negedge clk);
            rst = 1'b1;
            cpu_valid = 1'b0;
            repeat (3) @(posedge clk);
            @(negedge clk);
            rst = 1'b0;
        end
    endtask

    task automatic cpu_read_word;
        input [31:0] address;
        output [31:0] value;
        integer timeout;
        reg finished;
        begin
            @(negedge clk);
            cpu_valid = 1'b1;
            cpu_write = 1'b0;
            cpu_addr = address;
            cpu_wdata = 32'b0;
            cpu_wstrb = 4'b0000;
            timeout = 0;
            finished = 1'b0;
            while (!finished) begin
                @(posedge clk);
                timeout = timeout + 1;
                check(timeout < 1000, "CPU read timed out");
                if (cpu_ready) begin
                    value = cpu_rdata;
                    finished = 1'b1;
                end
            end
            @(negedge clk);
            cpu_valid = 1'b0;
            check(value === reference_mem[memory_index(address)],
                  "CPU read disagreed with independent reference memory");
        end
    endtask

    task automatic cpu_write_word;
        input [31:0] address;
        input [31:0] value;
        input [3:0] strobes;
        integer timeout;
        reg finished;
        begin
            @(negedge clk);
            cpu_valid = 1'b1;
            cpu_write = 1'b1;
            cpu_addr = address;
            cpu_wdata = value;
            cpu_wstrb = strobes;
            timeout = 0;
            finished = 1'b0;
            while (!finished) begin
                @(posedge clk);
                timeout = timeout + 1;
                check(timeout < 1000, "CPU write timed out");
                if (cpu_ready)
                    finished = 1'b1;
            end
            @(negedge clk);
            cpu_valid = 1'b0;
            reference_mem[memory_index(address)] =
                merge_bytes(reference_mem[memory_index(address)], value, strobes);
        end
    endtask

    assign mem_ready = memory_active && (memory_delay == 0);
    assign mem_rdata = backing_mem[memory_index(held_mem_addr)];

    always #5 clk = ~clk;

    always @(posedge clk) begin
        if (rst) begin
            memory_active <= 1'b0;
            memory_delay <= 0;
        end else if (memory_active) begin
            check(mem_valid === 1'b1,
                  "cache dropped mem_valid before mem_ready completion");
            check(mem_write === held_mem_write,
                  "cache changed mem_write while memory request stalled");
            check(mem_addr === held_mem_addr,
                  "cache changed mem_addr while memory request stalled");
            check(mem_wdata === held_mem_wdata,
                  "cache changed mem_wdata while memory request stalled");
            check(mem_wstrb === held_mem_wstrb,
                  "cache changed mem_wstrb while memory request stalled");
            if (memory_delay != 0) begin
                memory_delay <= memory_delay - 1;
            end else begin
                if (held_mem_write) begin
                    backing_mem[memory_index(held_mem_addr)] <=
                        merge_bytes(backing_mem[memory_index(held_mem_addr)],
                                    held_mem_wdata, held_mem_wstrb);
                    memory_writes <= memory_writes + 1;
                end else begin
                    memory_reads <= memory_reads + 1;
                end
                memory_active <= 1'b0;
                random_state <= {random_state[30:0],
                                 random_state[31] ^ random_state[21]
                                 ^ random_state[1] ^ random_state[0]};
            end
        end else if (mem_valid) begin
            memory_active <= 1'b1;
            held_mem_write <= mem_write;
            held_mem_addr <= mem_addr;
            held_mem_wdata <= mem_wdata;
            held_mem_wstrb <= mem_wstrb;
            if (forced_delay >= 0)
                memory_delay <= forced_delay;
            else begin
                memory_delay <= random_state[2:0];
                random_delays_seen[random_state[2:0]] <= 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            cpu_stalled <= 1'b0;
            completions_since_reset <= 0;
            check(cpu_ready === 1'b0, "cpu_ready asserted during reset");
            check(mem_valid === 1'b0, "mem_valid asserted during reset");
        end else begin
            if (cpu_valid && cpu_ready) begin
                cpu_completions <= cpu_completions + 1;
                completions_since_reset <= completions_since_reset + 1;
                cpu_stalled <= 1'b0;
            end else if (cpu_valid) begin
                if (!cpu_stalled) begin
                    held_cpu_write <= cpu_write;
                    held_cpu_addr <= cpu_addr;
                    held_cpu_wdata <= cpu_wdata;
                    held_cpu_wstrb <= cpu_wstrb;
                    cpu_stalled <= 1'b1;
                end else begin
                    check(cpu_write === held_cpu_write,
                          "CPU request changed cpu_write while stalled");
                    check(cpu_addr === held_cpu_addr,
                          "CPU request changed cpu_addr while stalled");
                    check(cpu_wdata === held_cpu_wdata,
                          "CPU request changed cpu_wdata while stalled");
                    check(cpu_wstrb === held_cpu_wstrb,
                          "CPU request changed cpu_wstrb while stalled");
                end
            end else begin
                cpu_stalled <= 1'b0;
            end
        end
    end

    initial begin
        clk = 1'b0;
        rst = 1'b0;
        cpu_valid = 1'b0;
        cpu_write = 1'b0;
        cpu_addr = 32'b0;
        cpu_wdata = 32'b0;
        cpu_wstrb = 4'b0;
        memory_active = 1'b0;
        memory_delay = 0;
        forced_delay = -1;
        random_state = 32'h1ace_b00c;
        memory_reads = 0;
        memory_writes = 0;
        random_delays_seen = 8'b0;
        cpu_completions = 0;
        completions_since_reset = 0;
        cpu_stalled = 1'b0;

        for (i = 0; i < MEM_WORDS; i = i + 1) begin
            backing_mem[i] = 32'h4100_0000 ^ (i * 32'h0001_0203);
            reference_mem[i] = backing_mem[i];
        end

        addr_a = make_addr(1, 1, 0);
        addr_b = make_addr(2, 1, 0);
        addr_c = make_addr(3, 1, 0);
        addr_d = make_addr(20, 2 % SETS, WORDS_PER_LINE-1);
        addr_e = make_addr(21, 2 % SETS, WORDS_PER_LINE-1);
        addr_f = make_addr(22, 2 % SETS, WORDS_PER_LINE-1);

        apply_reset();
        check(hit_count == 0 && miss_count == 0 && writeback_count == 0,
              "reset did not clear counters");

        cpu_read_word(addr_a, read_value);
        check(miss_count == 1 && hit_count == 0,
              "cold access was not counted as one miss");
        cpu_read_word(addr_a, read_value);
        cpu_write_word(addr_a, 32'ha1b2_c3d4, 4'b0101);
        cpu_read_word(addr_a, read_value);
        cpu_read_word(addr_b, read_value);
        cpu_write_word(addr_b, 32'h89ab_cdef, 4'b1111);
        cpu_read_word(addr_a, read_value);
        cpu_read_word(addr_c, read_value);
        check(backing_mem[memory_index(addr_b)] ===
              reference_mem[memory_index(addr_b)],
              "dirty least-recently-used way was not written back");
        cpu_read_word(addr_b, read_value);
        check(backing_mem[memory_index(addr_a)] ===
              reference_mem[memory_index(addr_a)],
              "partial-byte dirty line did not persist on eviction");
        check(hit_count == 5 && miss_count == 4 && writeback_count == 2,
              "directed hit/miss/writeback counters were wrong");
        check(memory_reads == 4 * WORDS_PER_LINE,
              "directed misses issued duplicate or missing refill reads");
        check(memory_writes == 2 * WORDS_PER_LINE,
              "directed evictions issued duplicate or missing writes");

        /* Abort a refill. The request must not complete or reappear after reset. */
        forced_delay = 7;
        completion_snapshot = cpu_completions;
        @(negedge clk);
        cpu_valid = 1'b1;
        cpu_write = 1'b0;
        cpu_addr = make_addr(40, 0, 0);
        cpu_wdata = 0;
        cpu_wstrb = 0;
        wait (mem_valid && !mem_write);
        repeat (2) @(posedge clk);
        @(negedge clk);
        check(memory_active && memory_delay > 0,
              "refill was not actively stalled before reset");
        rst = 1'b1;
        cpu_valid = 1'b0;
        repeat (3) @(posedge clk);
        check(cpu_completions == completion_snapshot,
              "reset-aborted refill completed a CPU request");
        @(negedge clk);
        rst = 1'b0;
        forced_delay = -1;
        check(hit_count == 0 && miss_count == 0 && writeback_count == 0,
              "activity reset did not clear counters");
        cpu_read_word(make_addr(40, 0, 0), read_value);
        check(miss_count == 1, "reset did not invalidate cache lines");

        /* Abort an unaccepted dirty writeback and prove memory was untouched. */
        cpu_read_word(addr_d, read_value);
        cpu_write_word(addr_d, 32'h1357_9bdf, 4'b1111);
        cpu_read_word(addr_e, read_value);
        backing_snapshot = backing_mem[memory_index(addr_d)];
        memory_write_snapshot = memory_writes;
        forced_delay = 7;
        completion_snapshot = cpu_completions;
        @(negedge clk);
        cpu_valid = 1'b1;
        cpu_write = 1'b0;
        cpu_addr = addr_f;
        cpu_wdata = 0;
        cpu_wstrb = 0;
        wait (mem_valid && mem_write);
        repeat (2) @(posedge clk);
        @(negedge clk);
        check(memory_active && memory_delay > 0,
              "writeback was not actively stalled before reset");
        rst = 1'b1;
        cpu_valid = 1'b0;
        repeat (3) @(posedge clk);
        check(cpu_completions == completion_snapshot,
              "reset-aborted eviction completed a CPU request");
        check(backing_mem[memory_index(addr_d)] == backing_snapshot,
              "reset-aborted memory write changed backing memory");
        check(memory_writes == memory_write_snapshot,
              "reset-aborted memory write was accepted");
        @(negedge clk);
        rst = 1'b0;
        forced_delay = -1;
        reference_mem[memory_index(addr_d)] =
            backing_mem[memory_index(addr_d)];
        cpu_read_word(addr_d, read_value);

        cpu_write_word(addr_d, 32'h0000_00a5, 4'b0001);
        cpu_write_word(addr_d, 32'h0000_5a00, 4'b0010);
        cpu_write_word(addr_d, 32'h003c_0000, 4'b0100);
        cpu_write_word(addr_d, 32'hc300_0000, 4'b1000);
        cpu_read_word(addr_d, read_value);
        check(read_value == 32'hc33c_5aa5,
              "one or more individual byte strobes did not select its lane");

        /* Deterministic randomized traffic checks data and all byte lanes. */
        for (random_iteration = 0; random_iteration < 96;
             random_iteration = random_iteration + 1) begin
            random_state = random_state ^ (32'h9e37_79b9 + random_iteration);
            random_addr = make_addr(50 + (random_state[7:4] % 6),
                                    random_state[11:8] % SETS,
                                    random_state[15:12] % WORDS_PER_LINE);
            if (random_state[0]) begin
                write_value = random_state ^ (random_iteration * 32'h0101_0101);
                case (random_state[3:2])
                    2'd0: write_mask = 4'b0001;
                    2'd1: write_mask = 4'b0010;
                    2'd2: write_mask = 4'b0100;
                    default: write_mask = 4'b1000;
                endcase
                cpu_write_word(random_addr, write_value, write_mask);
                cpu_read_word(random_addr, read_value);
            end else begin
                cpu_read_word(random_addr, read_value);
            end
        end

        check(hit_count + miss_count == completions_since_reset,
              "hit plus miss count did not equal completed CPU requests");
        check(memory_reads > 0 && memory_writes > 0,
              "test did not exercise both backing-memory directions");
        check(random_delays_seen == 8'hff,
              "deterministic memory model did not cover delays 0 through 7");
        $display("TB_CACHE_PASS SETS=%0d WORDS_PER_LINE=%0d cpu=%0d mem_reads=%0d mem_writes=%0d hits=%0d misses=%0d writebacks=%0d",
                 SETS, WORDS_PER_LINE, cpu_completions, memory_reads,
                 memory_writes, hit_count, miss_count, writeback_count);
        $finish;
    end

    initial begin
        #2000000;
        $display("TB_CACHE_FAIL: global timeout");
        $fatal(1);
    end
endmodule

tests/tb_cp0.sv.text:
`timescale 1ns/1ps
module tb_cp0;
reg clk=0,rst=1;
always #5 clk=~clk;
reg [4:0] read_addr=0,write_addr=0,exception_code=0;
reg [31:0] write_data=0,exception_pc=0,exception_badvaddr=0;
reg write_valid=0,exception_valid=0,exception_bd=0,eret=0;
reg [5:0] hw_irq=0;
wire [31:0] read_data,status,cause,epc,badvaddr;
wire irq_pending;
integer checks=0,failures=0;
cp0 dut(.*);
task check(input bit condition,input [511:0] label);
begin checks=checks+1;if(!condition) begin failures=failures+1;$display("FAIL %s",label);end end
endtask
task wr(input [4:0] addr,input [31:0] data);
begin @(negedge clk);write_valid=1;write_addr=addr;write_data=data;@(negedge clk);write_valid=0;end
endtask
task fault(input [4:0] code,input [31:0] pc,input bit bd,input [31:0] bad);
begin @(negedge clk);exception_valid=1;exception_code=code;exception_pc=pc;
exception_bd=bd;exception_badvaddr=bad;@(negedge clk);exception_valid=0;end
endtask
task reset_cp0;
begin @(negedge clk);rst=1;@(negedge clk);rst=0;#1;end
endtask
initial begin
repeat(3) @(negedge clk);rst=0;#1;
check(status==32'h00400000,"reset status");check(!irq_pending,"reset interrupts masked");
wr(12,32'h00000401);hw_irq=6'b000001;#1;check(irq_pending,"enabled external interrupt");
fault(0,32'hbfc00080,0,0);#1;
check(status[1] && !irq_pending,"EXL masks interrupt");check(epc==32'hbfc00080,"interrupt EPC");
fault(4,32'hbfc000a0,1,32'h00000103);#1;
check(epc==32'hbfc00080 && !cause[31],"nested exception preserves first EPC BD");
check(badvaddr==32'h103 && cause[6:2]==4,"AdEL updates bad address code");
@(negedge clk);eret=1;@(negedge clk);eret=0;hw_irq=0;#1;check(!status[1],"eret clears EXL");
fault(5,32'hbfc00100,1,32'h105);#1;
check(epc==32'hbfc00100 && cause[31],"delay slot branch EPC and BD");
check(badvaddr==32'h105,"AdES bad address");
wr(14,32'h12345678);check(epc==32'h12345678,"MTC0 EPC");
read_addr=14;#1;check(read_data==epc,"MFC0 EPC");
wr(12,32'h00000101);wr(13,32'h00000100);#1;
check(irq_pending && cause[8],"software interrupt pending");
wr(13,0);#1;check(!irq_pending,"software pending clear");
wr(12,32'h00008001);wr(9,0);wr(11,12);
repeat(14) @(negedge clk);#1;check(irq_pending && cause[30] && cause[15],"Count Compare timer");
wr(11,100);#1;check(!irq_pending && !cause[30],"Compare write acknowledges timer");
read_addr=31;#1;check(read_data==0,"unsupported register read");
reset_cp0;
check(epc==0 && badvaddr==0 && !cause[30],"reset clears exception state");

@(negedge clk);write_valid=1;write_addr=11;write_data=100;
@(negedge clk);write_addr=9;write_data=99;
@(negedge clk);write_data=0;
@(negedge clk);write_valid=0;read_addr=9;#1;
check(read_data==0,"Count write commits value away from imminent match");
check(!cause[30],"Count write away from Compare does not set timer");

reset_cp0;
wr(11,100);wr(9,100);read_addr=9;#1;
check(read_data==100 && cause[30],"Count write equal to Compare sets timer");

reset_cp0;
wr(11,0);wr(9,32'hffffffff);@(negedge clk);read_addr=9;#1;
check(read_data==0 && cause[30],"normal Count increment wraps and matches Compare");

reset_cp0;
wr(11,100);wr(9,100);wr(11,102);read_addr=9;#1;
check(read_data==102 && !cause[30],"Compare write clears timer at equal committed Count");

reset_cp0;
wr(9,10);
exception_valid=1;exception_code=0;exception_pc=32'h1000;
write_valid=1;write_addr=9;write_data=777;
@(negedge clk);exception_valid=0;write_valid=0;read_addr=9;#1;
check(read_data==11,"exception suppresses Count write but not increment");

reset_cp0;
wr(9,20);eret=1;write_valid=1;write_addr=9;write_data=777;
@(negedge clk);eret=0;write_valid=0;read_addr=9;#1;
check(read_data==21,"eret suppresses Count write but not increment");
if(failures==0)$display("PASS CP0 checks=%0d",checks);
else $display("FAIL CP0 failures=%0d",failures);
$finish;
end
initial begin #10000;$fatal(1,"CP0 timeout");end
endmodule

tests/tb_cpu_cache.sv.text:
`timescale 1ns/1ps
module tb_cpu_cache;
`ifdef JOINT_SMALL
localparam SETS=4, WORDS=2;
`else
localparam SETS=16, WORDS=4;
`endif
reg clk=0;always #5 clk=~clk;
reg rst=1;
reg [31:0] rom[0:1023],memory[0:8191],expected_memory[0:8191];
wire [31:0] ia,ba,bw,br,ma,mw,mr;
wire bv,bwrite,mv,mwrite;wire [3:0] bs,ms;
reg ready_back=0,ready_mmio=0;
wire tv,tw,ev,eb;wire [31:0] tp,ti,td,tma,tmd,ee,cycles,retired,stalls,hits,misses,writebacks;
wire [4:0] tr,ec;wire [3:0] tm;
assign br=memory[ba[14:2]];
assign mr=32'h13579bdf;
cached_cpu #(.RESET_PC(0),.SETS(SETS),.WORDS_PER_LINE(WORDS)) dut(
 .clk(clk),.rst(rst),.imem_addr(ia),.imem_rdata(rom[ia[11:2]]),.hw_irq(6'b0),
 .mem_valid(bv),.mem_write(bwrite),.mem_addr(ba),.mem_wdata(bw),.mem_wstrb(bs),.mem_ready(ready_back),.mem_rdata(br),
 .mmio_valid(mv),.mmio_write(mwrite),.mmio_addr(ma),.mmio_wdata(mw),.mmio_wstrb(ms),.mmio_ready(ready_mmio),.mmio_rdata(mr),
 .trace_valid(tv),.trace_pc(tp),.trace_instr(ti),.trace_we(tw),.trace_rd(tr),.trace_wdata(td),
 .trace_mem_we(tm),.trace_mem_addr(tma),.trace_mem_wdata(tmd),
 .exception_valid(ev),.exception_code(ec),.exception_epc(ee),.exception_bd(eb),
 .cycle_count(cycles),.retired_count(retired),.stall_count(stalls),
 .hit_count(hits),.miss_count(misses),.writeback_count(writebacks));
integer mode=0,tick=0,i,j,k,n,got,trace_fd,request_fd,counts_fd;
integer expected_requests,requests_done=0,mmio_stores=0,back_reads=0,back_writes=0;
integer eh,emiss,ewb,emmio,adjacent=0,trace_file,bus_file;
reg [31:0] ep,ei,ewe,erd,ed,ems,ema,emd;
reg [31:0] qwrite,qaddr,qdata,qstrobe,qread;
reg [31:0] random_state=32'hc01dcafe;
reg held_cpu=0,held_back=0,held_mmio=0,last_back=0;
reg [68:0] request_cpu,request_back,request_mmio;

always @(negedge clk)begin
 if(rst)begin ready_back=0;ready_mmio=0;random_state=32'hc01dcafe;end
 else begin
  random_state=random_state^(random_state<<13);
  random_state=random_state^(random_state>>17);
  random_state=random_state^(random_state<<5);
  ready_back=(mode==0)||(mode==1&&random_state[1:0]==0)||(mode==2&&tick%13==5);
  ready_mmio=(mode==0)||(random_state[5:3]==3);
 end
end

always @(posedge clk)begin
 tick<=tick+1;
 if(rst)begin held_cpu<=0;held_back<=0;held_mmio<=0;last_back<=0;end
 else begin
  if(ev)$fatal(1,"FAIL unexpected exception code=%0d EPC=%h",ec,ee);
  if(held_cpu&&(!dut.cpu_valid||{dut.cpu_write,dut.cpu_addr,dut.cpu_wdata,dut.cpu_wstrb}!==request_cpu))$fatal(1,"FAIL unstable CPU request");
  if(held_back&&(!bv||{bwrite,ba,bw,bs}!==request_back))$fatal(1,"FAIL unstable backing request");
  if(held_mmio&&(!mv||{mwrite,ma,mw,ms}!==request_mmio))$fatal(1,"FAIL unstable MMIO request");
  held_cpu<=dut.cpu_valid&&!dut.cpu_ready;request_cpu<={dut.cpu_write,dut.cpu_addr,dut.cpu_wdata,dut.cpu_wstrb};
  held_back<=bv&&!ready_back;request_back<={bwrite,ba,bw,bs};
  held_mmio<=mv&&!ready_mmio;request_mmio<={mwrite,ma,mw,ms};
  if(mv&&bv)$fatal(1,"FAIL cache and MMIO active together");
  if(bv&&ba>=32'h8000)$fatal(1,"FAIL backing address outside RAM %h",ba);
  if(mv&&ma[31:16]!=16'hffff)$fatal(1,"FAIL MMIO decode %h",ma);
  if(bv&&ready_back)begin
   if(last_back)adjacent=adjacent+1;
   if(ba[1:0]!=0||bs!==(bwrite?4'hf:4'h0))$fatal(1,"FAIL backing word protocol");
   if(bwrite)begin
    back_writes=back_writes+1;
    for(k=0;k<4;k=k+1)if(bs[k])memory[ba[14:2]][k*8+:8]<=bw[k*8+:8];
   end else back_reads=back_reads+1;
  end
  last_back<=bv&&ready_back;
  if(mv&&ready_mmio&&mwrite)mmio_stores=mmio_stores+1;
  if(dut.cpu_valid&&dut.cpu_ready)begin
   if(requests_done>=expected_requests)$fatal(1,"FAIL duplicate CPU/MMIO completion");
   got=$fscanf(request_fd,"%h %h %h %h %h\n",qwrite,qaddr,qdata,qstrobe,qread);
   if(got!=5)$fatal(1,"FAIL request oracle truncated");
   if(dut.cpu_write!==qwrite[0]||dut.cpu_addr!==qaddr||dut.cpu_wstrb!==qstrobe[3:0]||
      (qwrite&&(dut.cpu_wdata!==qdata))||(!qwrite&&dut.cpu_rdata!==qread))
      $fatal(1,"FAIL CPU request row=%0d addr=%h/%h read=%h/%h",requests_done,dut.cpu_addr,qaddr,dut.cpu_rdata,qread);
   requests_done=requests_done+1;
  end
  if(tv)$fwrite(trace_file,"%0d,%0d,%h,%h,%b,%0d,%h,%h,%h,%h\n",mode,cycles,tp,ti,tw,tr,td,tm,tma,tmd);
  $fwrite(bus_file,"%0d,%0d,%b,%b,%h,%b,%b,%b,%h,%b,%b,%h,%0d,%0d,%0d\n",mode,cycles,dut.cpu_valid,dut.cpu_ready,dut.cpu_addr,bv,ready_back,bwrite,ba,mv,ready_mmio,ma,hits,misses,writebacks);
 end
end

initial begin
 $readmemh("cache_program.hex",rom);$readmemh("cache_memory.hex",expected_memory);
 trace_file=$fopen($sformatf("cache_retirements_%0d_%0d.csv",SETS,WORDS),"w");
 bus_file=$fopen($sformatf("cache_bus_%0d_%0d.csv",SETS,WORDS),"w");
 $fwrite(trace_file,"mode,cycle,pc,instr,we,rd,wdata,mem_strobe,mem_addr,mem_data\n");
 $fwrite(bus_file,"mode,cycle,cpu_valid,cpu_ready,cpu_addr,back_valid,back_ready,back_write,back_addr,mmio_valid,mmio_ready,mmio_addr,hits,misses,writebacks\n");
 counts_fd=$fopen("cache_counts.txt","r");got=$fscanf(counts_fd,"%d %d %d %d\n",eh,emiss,ewb,emmio);$fclose(counts_fd);
 if(got!=4)$fatal(1,"FAIL counts oracle truncated");
 for(mode=0;mode<3;mode=mode+1)begin
  rst=1;repeat(4)@(negedge clk);
  for(i=0;i<8192;i=i+1)memory[i]=0;
  requests_done=0;mmio_stores=0;back_reads=0;back_writes=0;adjacent=0;
  trace_fd=$fopen("cache_trace.txt","r");got=$fscanf(trace_fd,"%d\n",n);
  request_fd=$fopen("cache_requests.txt","r");got=$fscanf(request_fd,"%d\n",expected_requests);
  #1;rst=0;
  for(j=0;j<n;j=j+1)begin
   got=$fscanf(trace_fd,"%h %h %h %h %h %h %h %h\n",ep,ei,ewe,erd,ed,ems,ema,emd);
   if(got!=8)$fatal(1,"FAIL trace oracle truncated");
   @(posedge clk);while(!tv)@(posedge clk);
   if(tp!==ep||ti!==ei||tw!==ewe[0]||(tw&&(tr!==erd[4:0]||td!==ed))||tm!==ems[3:0]||(tm&&(tma!==ema||tmd!==emd)))
    $fatal(1,"FAIL retirement row=%0d mode=%0d PC=%h/%h data=%h/%h",j,mode,tp,ep,td,ed);
  end
  @(negedge clk);
  if(retired!=n||requests_done!=expected_requests)$fatal(1,"FAIL retirement/request count");
  if(hits!=eh||misses!=emiss||writebacks!=ewb)$fatal(1,"FAIL counters hit=%0d/%0d miss=%0d/%0d wb=%0d/%0d",hits,eh,misses,emiss,writebacks,ewb);
  if(back_reads!=emiss*WORDS||back_writes!=ewb*WORDS)$fatal(1,"FAIL backing transaction count");
  if(mmio_stores!=emmio)$fatal(1,"FAIL MMIO duplicate/missing %0d/%0d",mmio_stores,emmio);
  if(mode==0&&adjacent==0)$fatal(1,"FAIL continuous ready coverage absent");
  for(i=0;i<8192;i=i+1)if(memory[i]!==expected_memory[i])$fatal(1,"FAIL final backing memory word=%0d actual=%h expected=%h",i,memory[i],expected_memory[i]);
  $display("JOINT sets=%0d words=%0d mode=%0d retirements=%0d cycles=%0d stalls=%0d hits=%0d misses=%0d writebacks=%0d MMIO_stores=%0d back_reads=%0d back_writes=%0d adjacent=%0d",SETS,WORDS,mode,retired,cycles,stalls,hits,misses,writebacks,mmio_stores,back_reads,back_writes,adjacent);
  $fclose(trace_fd);$fclose(request_fd);
 end
 rst=1;$fclose(trace_file);$fclose(bus_file);
 $display("PASS cpu-cache SETS=%0d WORDS=%0d",SETS,WORDS);$finish;
end
initial begin #2000000;$fatal(1,"FAIL cpu-cache watchdog");end
endmodule

tests/tb_lab1.sv.text:
`timescale 1ns/1ps
`ifndef LAB1_DUT
`define LAB1_DUT lab1_num_led
`endif
module tb_lab1;
 reg clk=0,rst=0,center_btn_key=0;
 reg [7:0] switch=0;
 wire [6:0] digital_num0,digital_num1;
 wire [7:0] digital_cs;
 reg [31:0] expected=0;
 integer byte_index=0, checks=0;
 always #5 clk=~clk;
 `LAB1_DUT #(.COUNTER_WIDTH(4)) dut(.*);
 // Independent oracle: lit segment letters, in the course abcdefg order.
 function [6:0] glyph(input integer n);
  case(n)
   0:glyph=126;1:glyph=48;2:glyph=109;3:glyph=121;
   4:glyph=51;5:glyph=91;6:glyph=95;7:glyph=112;
   8:glyph=127;9:glyph=123;10:glyph=119;11:glyph=31;
   12:glyph=78;13:glyph=61;14:glyph=79;15:glyph=71;
  endcase
 endfunction
 task check_display;
  integer seen,phase;
  begin
   seen=0;
   repeat(32)begin
    @(negedge clk);
    case(digital_cs)
     8'h11:phase=0;8'h22:phase=1;8'h44:phase=2;8'h88:phase=3;
     default:$fatal(1,"FAIL LAB1 invalid select %h",digital_cs);
    endcase
    if(digital_num0!==glyph((expected>>(phase*4))&15) ||
       digital_num1!==glyph((expected>>(16+phase*4))&15))
     $fatal(1,"FAIL LAB1 value=%h phase=%0d segments=%h/%h",expected,phase,digital_num0,digital_num1);
    seen=seen|(1<<phase);checks=checks+1;
   end
   if(seen!=15)$fatal(1,"FAIL LAB1 missing scan phase");
  end
 endtask
 task press(input [7:0] value);
  begin
   @(negedge clk);switch=value;center_btn_key=1;
   repeat(50)@(negedge clk);
   expected[byte_index*8+:8]=value;byte_index=(byte_index+1)%4;
   check_display(); // prolonged hold must write exactly one byte
   center_btn_key=0;
   repeat(50)@(negedge clk);
   check_display();
  end
 endtask
 initial begin
  repeat(5)@(negedge clk);
  if(digital_cs!==0 || digital_num0!==0 || digital_num1!==0)$fatal(1,"FAIL LAB1 reset outputs");
  rst=1;repeat(5)@(negedge clk);check_display();
  switch=8'hff;center_btn_key=1;@(negedge clk);center_btn_key=0;
  repeat(50)@(negedge clk);check_display(); // reject a short pulse
  press(8'h10);press(8'h32);press(8'h54);press(8'h76);
  press(8'h98);press(8'hba);press(8'hdc);press(8'hfe);
  rst=0;center_btn_key=1;repeat(5)@(negedge clk);
  if(digital_cs!==0)$fatal(1,"FAIL LAB1 active reset");
  center_btn_key=0;expected=0;byte_index=0;rst=1;
  repeat(50)@(negedge clk);check_display();press(8'h1a);
  $display("PASS LAB1 checks=%0d all16glyphs fourphases bytewrap debounce heldbutton reset",checks);$finish;
 end
 initial begin #100000;$fatal(1,"FAIL LAB1 timeout");end
endmodule

tests/tb_lab3.sv.text:
`timescale 1ns/1ps
module tb_lab3;
 reg clk=0,rstn=0;
 reg [7:0] switch=0;
 reg mid_btn_key=0,left_btn_key=0,right_btn_key=0,up_btn_key=0,down_btn_key=0;
 wire [6:0] digital_num0,digital_num1;
 wire [7:0] digital_cs,led;
 single_cycle dut(.*);
 always #5 clk=~clk;
 integer mode=0,cycles=0,stores=0,displays=0,cases=0,expected_sum=0;
 integer golden[0:19];
 integer boundaries[0:5];
 reg checking_sum=0;
 integer display_writes=0;
 task reset_cpu;
  begin
   @(negedge clk);rstn=0;mid_btn_key=0;right_btn_key=0;up_btn_key=0;
   repeat(5)@(negedge clk);rstn=1;
  end
 endtask
 task await_reg(input integer regno,input integer expected);
  integer wait_cycles;
  begin
   wait_cycles=0;
   while(dut.mycpu0.core.regs[regno]!==expected && wait_cycles<3000000)begin
    @(negedge clk);wait_cycles=wait_cycles+1;
   end
   if(wait_cycles==3000000)$fatal(1,"FAIL LAB3 input r%0d expected=%0d",regno,expected);
   if(led!==expected[7:0])begin
    repeat(3)@(negedge clk);
    if(led!==expected[7:0])$fatal(1,"FAIL LAB3 input LED");
   end
  end
 endtask
 task add_case(input integer a,b);
  integer before_writes,wait_cycles;
  begin
   reset_cpu();repeat(30)@(negedge clk);
   switch=a;up_btn_key=1;
   // For zero inputs, await_reg could already match reset; wait for actual
   // debounced input and one full program polling loop before changing switch.
   wait(dut.confreg0.up_btn_key_r===1);repeat(mode==3 ? 100 : 600000)@(negedge clk);await_reg(11,a);
   up_btn_key=0;wait(dut.confreg0.up_btn_key_r===0);
   switch=b;right_btn_key=1;
   wait(dut.confreg0.right_btn_key_r===1);repeat(mode==3 ? 100 : 600000)@(negedge clk);await_reg(12,b);
   right_btn_key=0;wait(dut.confreg0.right_btn_key_r===0);
   expected_sum=a+b;checking_sum=1;before_writes=display_writes;mid_btn_key=1;wait_cycles=0;
   while(display_writes==before_writes && wait_cycles<3000000)begin
    @(negedge clk);wait_cycles=wait_cycles+1;
   end
   if(wait_cycles==3000000)$fatal(1,"FAIL LAB3 adder timeout %0d+%0d",a,b);
   repeat(20)@(negedge clk);
   if(dut.confreg0.digital_num_v!==expected_sum || led!==expected_sum[7:0])
    $fatal(1,"FAIL LAB3 adder %0d+%0d actual display=%0d led=%0d",a,b,dut.confreg0.digital_num_v,led);
   repeat(100)@(negedge clk);
   if(display_writes!=before_writes+1)$fatal(1,"FAIL LAB3 held mid repeats sum");
   mid_btn_key=0;checking_sum=0;cases=cases+1;
  end
 endtask
 initial begin
  if($test$plusargs("MODE1"))mode=1;
  if($test$plusargs("MODE2"))mode=2;
  if($test$plusargs("MODE3"))mode=3;
  golden[0]=2;golden[1]=3;
  for(integer i=2;i<20;i=i+1)golden[i]=golden[i-1]+golden[i-2];
  boundaries[0]=0;boundaries[1]=1;boundaries[2]=127;boundaries[3]=128;boundaries[4]=254;boundaries[5]=255;
  if(mode<2)begin
   reset_cpu();
   wait(displays==(mode==0 ? 1 : 20));@(negedge clk);
   if(stores!=20)$fatal(1,"FAIL LAB3 Fibonacci store count %0d",stores);
   for(integer i=0;i<20;i=i+1)
    if(dut.data_ram_4k.mem[i]!==golden[i])$fatal(1,"FAIL LAB3 Fibonacci RAM index=%0d",i);
   $display("PASS LAB3 fibonacci mode=%0d stores=%0d displays=%0d last=%0d cycles=%0d",mode,stores,displays,golden[19],cycles);$finish;
  end else begin
   if(mode==2)add_case(255,255);
   else for(integer a=0;a<6;a=a+1)for(integer b=0;b<6;b=b+1)add_case(boundaries[a],boundaries[b]);
   $display("PASS LAB3 adder mode=%0d cases=%0d cycles=%0d",mode,cases,cycles);$finish;
  end
 end
 always @(posedge clk)if(rstn)begin
  cycles=cycles+1;
  if(dut.mycpu0.illegal)$fatal(1,"FAIL LAB3 illegal pc=%h",dut.inst_rom_addr);
  if(dut.data_ram_wen)begin
   if(dut.data_ram_addr[31:16]!=16'hbfaf)begin
    if(mode>=2 || stores>=20 || dut.data_ram_addr!==32'hbfc10000+stores*4 || dut.data_ram_wdata!==golden[stores])
     $fatal(1,"FAIL LAB3 Fibonacci store index=%0d address=%h data=%h",stores,dut.data_ram_addr,dut.data_ram_wdata);
    stores=stores+1;
   end else if(dut.data_ram_addr==32'hbfaf8000)begin
    display_writes=display_writes+1;
    if(mode<2)begin
     if(displays>=20 || dut.data_ram_wdata!==golden[displays])$fatal(1,"FAIL LAB3 Fibonacci display index=%0d value=%0d",displays,dut.data_ram_wdata);
     displays=displays+1;
    end else if(checking_sum && dut.data_ram_wdata!==expected_sum)$fatal(1,"FAIL LAB3 sum expected=%0d actual=%0d",expected_sum,dut.data_ram_wdata);
   end
  end
  if(cycles>250000000)$fatal(1,"FAIL LAB3 timeout");
 end
endmodule

tests/tb_pipeline.sv.text:
`timescale 1ns/1ps
module tb_pipeline;
reg clk=0;always #5 clk=~clk;
reg rst=1;wire [31:0] ia,da,dw;reg [31:0] rom[0:4095],mem[0:255];wire [3:0] ds;wire dv,write;
integer cycle=0,mode=0;reg force_wait=0;wire ready=!force_wait&&((mode==0)||(mode==1&&cycle%7<2)||(mode>=2&&cycle%13==5));reg [5:0] irq=0;
wire tv,tw;wire [31:0] tp,ti,td;wire [4:0] tr;wire [3:0] tm;wire [31:0] tma,tmd;wire ev,eb;wire[4:0] ec;wire[31:0] ee,cc,rc,sc;
pipeline_cpu #(.RESET_PC(0),.EXCEPTION_PC(32'h1000)) dut(.clk(clk),.rst(rst),.imem_addr(ia),.imem_rdata(rom[ia[13:2]]),.dmem_valid(dv),.dmem_write(write),.dmem_addr(da),.dmem_wdata(dw),.dmem_wstrb(ds),.dmem_ready(ready),.dmem_rdata(mem[da[9:2]]),.hw_irq(irq),.trace_valid(tv),.trace_pc(tp),.trace_instr(ti),.trace_we(tw),.trace_rd(tr),.trace_wdata(td),.trace_mem_we(tm),.trace_mem_addr(tma),.trace_mem_wdata(tmd),.exception_valid(ev),.exception_code(ec),.exception_epc(ee),.exception_bd(eb),.cycle_count(cc),.retired_count(rc),.stall_count(sc));
integer fd,n,i,j,k,got,stagefile,retirefile,scenario,excount,stores,store_counts[0:63],irqcase;reg[31:0] ep,ei,ew,er,ed,em,ema,emd;reg held=0;reg[68:0] request;
reg fault_testing=0;reg[4:0] expected_code;reg[31:0] expected_epc,expected_bad;reg expected_bd;
reg irq_testing=0,irq_armed=0;reg[31:0] irq_epc;
function[31:0] encI(input[5:0] op,input[4:0] rs,rt,input[15:0] imm);encI={op,rs,rt,imm};endfunction
task reset_case;
 begin
  rst=1;irq=0;repeat(3)@(negedge clk);
  for(i=0;i<4096;i=i+1)rom[i]=0;
  for(i=0;i<256;i=i+1)mem[i]=0;
  for(i=0;i<64;i=i+1)store_counts[i]=0;
  excount=0;stores=0;
 end
endtask
always @(posedge clk) begin
 cycle<=cycle+1;
 if(!rst)begin
  if(held && (!dv || {write,da,dw,ds}!==request))$fatal(1,"FAIL request unstable");
  held<=dv&&!ready;request<={write,da,dw,ds};
  if(dv&&ready&&write)begin
   if(da==0)stores=stores+1;
   if(irq_testing)store_counts[da[7:2]]=store_counts[da[7:2]]+1;
   for(k=0;k<4;k=k+1)if(ds[k])mem[da[9:2]][k*8+:8]<=dw[k*8+:8];
  end
  if(ev&&fault_testing)begin
   excount=excount+1;
   if(scenario==12)irq<=0;
   if(ec!==expected_code||ee!==expected_epc||eb!==expected_bd)$fatal(1,"FAIL exception case %d code %d/%d EPC %h/%h BD %d/%d",scenario,ec,expected_code,ee,expected_epc,eb,expected_bd);
  end
  if(tv)$fwrite(retirefile,"%0d,%0d,%h,%h,%b,%0d,%h,%h,%h,%h\n",mode,cycle,tp,ti,tw,tr,td,tm,tma,tmd);
  if(ev&&irq_testing)begin
   excount=excount+1;irq_epc=ee;irq<=0;
   if(ec!=0||eb||excount!=1)$fatal(1,"FAIL interrupt precision case %d",irqcase);
   if(irqcase==0&&ee!=28)$fatal(1,"FAIL interrupted store restart EPC %h",ee);
   if(irqcase==1&&ee!=40)$fatal(1,"FAIL delay-slot IRQ EPC %h",ee);
  end
  $fwrite(stagefile,"%0d,%0d,%b,%h,%h,%b,%h,%h,%b,%h,%h,%b,%h,%h,%b,%h,%h,%b,%b\n",mode,cycle,dut.if_valid,ia,dut.if_instr,dut.id_valid,dut.id_pc,dut.id_instr,dut.ex_valid,dut.ex_pc,dut.ex_instr,dut.mem_valid,dut.mem_pc,dut.mem_instr,dut.wb_valid,dut.wb_pc,dut.wb_instr,dv,ready);
 end else held<=0;
end
always @(negedge clk)begin
 if(!rst&&irq_testing&&irq_armed)begin
  if((irqcase==0&&dv&&write&&da==0&&!ready)||(irqcase==1&&dut.ex_valid&&dut.ex_bd))begin irq=1;irq_armed=0;end
 end
end
initial begin
 stagefile=$fopen("pipeline_stages.csv","w");$fwrite(stagefile,"mode,cycle,if_valid,if_pc,if_instr,id_valid,id_pc,id_instr,ex_valid,ex_pc,ex_instr,mem_valid,mem_pc,mem_instr,wb_valid,wb_pc,wb_instr,dmem_valid,dmem_ready\n");
 retirefile=$fopen("pipeline_retirements.csv","w");$fwrite(retirefile,"mode,cycle,pc,instr,we,rd,wdata,mem_strobe,mem_addr,mem_data\n");
 for(i=0;i<4096;i=i+1)rom[i]=0;
 $readmemh("pipeline_program.hex",rom);
 for(mode=0;mode<3;mode=mode+1)begin
  rst=1;repeat(3)@(negedge clk);for(i=0;i<256;i=i+1)mem[i]=0;rst=0;
  fd=$fopen("pipeline_expected.txt","r");got=$fscanf(fd,"%d\n",n);
  for(j=0;j<n;j=j+1)begin
   got=$fscanf(fd,"%h %h %h %h %h %h %h %h\n",ep,ei,ew,er,ed,em,ema,emd);
   @(posedge clk);while(!tv)begin if(ev)$fatal(1,"FAIL unexpected exception %d PC %h",ec,ee);@(posedge clk);end
   if(tp!==ep||ti!==ei||tw!==ew[0]||(tw&&(tr!==er[4:0]||td!==ed))||tm!==em[3:0]||(tm&&(tma!==ema||tmd!==emd)))$fatal(1,"FAIL row %d mode %d PC %h/%h data %h/%h we %d/%d mem %h/%h",j,mode,tp,ep,td,ed,tw,ew,tm,em);
  end
  $fclose(fd);@(negedge clk);
  if(rc!=n)$fatal(1,"FAIL retired counter");
  $display("TRACE mode=%0d retirements=%0d cycles=%0d stalls=%0d",mode,rc,cc,sc);
 end
 // Real exception handlers read CP0, change EPC, ERET and execute a marker store.
 fault_testing=1;mode=2;
 for(scenario=0;scenario<13;scenario=scenario+1)begin
  reset_case();
  expected_code=8;expected_epc=8;expected_bd=0;expected_bad=0;
  rom[0]=encI(9,0,1,55);rom[1]=encI(43,0,1,0);rom[2]=32'h0000000c;
  rom[3]=encI(43,0,1,4);rom[4]=encI(9,0,2,77);rom[5]=encI(43,0,2,8);
  case(scenario)
   1:begin rom[2]=32'h0000000d;expected_code=9;end
   2:begin rom[2]=32'hfc000000;expected_code=10;end
   3:begin rom[2]=encI(35,0,3,1);expected_code=4;expected_bad=1;end
   4:begin rom[2]=encI(43,0,1,2);expected_code=5;expected_bad=2;end
   5:begin rom[0]=encI(15,0,1,16'h8000);rom[2]=encI(8,1,3,16'hffff);expected_code=12;end
   6:begin
    rom[2]=encI(4,1,1,2);rom[3]=32'h0000000c;rom[4]=encI(43,0,1,4);rom[5]=encI(9,0,2,77);rom[6]=encI(43,0,2,8);expected_bd=1;
   end
   7:begin rom[2]=encI(4,1,1,2);rom[3]=32'h08000008;rom[4]=encI(43,0,1,4);rom[5]=encI(9,0,2,77);rom[6]=encI(43,0,2,8);expected_bd=1;expected_code=10;end
   8:begin rom[0]=encI(9,0,1,26);rom[2]=32'h00200008;rom[3]=0;rom[6]=encI(43,0,1,4);rom[8]=encI(9,0,2,77);rom[9]=encI(43,0,2,8);expected_epc=26;expected_code=4;expected_bad=26;end
   9:begin rom[0]=encI(15,0,1,16'h8000);rom[2]=32'h00211820;expected_code=12;end
   10:begin rom[0]=encI(15,0,1,16'h8000);rom[1]=encI(9,0,2,1);rom[2]=32'h00221822;expected_code=12;end
   11:begin rom[2]=encI(33,0,3,3);expected_code=4;expected_bad=3;end
   12:begin rom[0]=encI(13,0,2,16'h0401);rom[1]=32'h40826000;irq=1;end
  endcase
  rom[1024]=32'h40146800; // mfc0 r20,Cause
  rom[1025]=32'h40157000; // mfc0 r21,EPC
  rom[1026]=32'h40164000; // mfc0 r22,BadVAddr
  rom[1027]=32'h40176000; // mfc0 r23,Status
  rom[1028]=encI(9,0,24,scenario==8?32:(expected_bd?20:16));
  rom[1029]=32'h40987000; // mtc0 r24,EPC
  rom[1030]=32'h42000018;
  rst=0;
  while(mem[2]!==77)@(negedge clk);
  if(excount!=1||mem[1]!==0||dut.regs[21]!==expected_epc||dut.regs[20][6:2]!==expected_code||dut.regs[20][31]!==expected_bd||!dut.regs[23][1]||dut.status[1])$fatal(1,"FAIL handler case %d count %d",scenario,excount);
  if((expected_code==4||expected_code==5)&&dut.regs[22]!==expected_bad)$fatal(1,"FAIL badvaddr");
  if(scenario!=10&&scenario!=12&&stores!=1)$fatal(1,"FAIL older store repeated");
 end
 fault_testing=0;irq_testing=1;
 for(irqcase=0;irqcase<3;irqcase=irqcase+1)begin
  reset_case();irq_armed=irqcase!=2;
  rom[0]=encI(9,0,1,1);rom[1]=32'h40804800; // mtc0 zero,Count
  rom[2]=encI(9,0,2,80);rom[3]=32'h40825800; // Compare=80
  rom[4]=encI(13,0,2,irqcase==2?16'h8001:16'h0401);rom[5]=32'h40826000;
  rom[6]=encI(43,0,1,0);rom[7]=encI(9,1,1,1);rom[8]=encI(43,0,1,4);rom[9]=encI(9,1,1,1);
  if(irqcase==1)begin
   rom[6]=encI(4,1,1,3);rom[7]=encI(43,0,1,0);rom[8]=encI(43,0,1,200);rom[9]=0;
   rom[10]=encI(9,1,1,1);rom[11]=encI(43,0,1,4);rom[12]=encI(9,1,1,1);
  end
  for(j=2;j<20;j=j+1)begin
   rom[(irqcase==1?13:10)+(j-2)*2]=encI(43,0,1,j*4);
   rom[(irqcase==1?14:11)+(j-2)*2]=encI(9,1,1,1);
  end
  rom[50]=encI(9,0,3,77);rom[51]=encI(43,0,3,252);rom[52]=32'h08000034;
  rom[1024]=32'h40157000;rom[1025]=32'h40146800;
  rom[1026]=32'h40805800; // Clear timer by Compare write.
  rom[1027]=32'h42000018; // Return to original, uncommitted EPC.
  rst=0;
  while(mem[63]!==77)@(negedge clk);
  if(excount!=1||dut.regs[21]!==irq_epc||dut.status[1])$fatal(1,"FAIL IRQ resume case %d count %d",irqcase,excount);
  for(j=0;j<20;j=j+1)if(mem[j]!==j+1||store_counts[j]!=1)$fatal(1,"FAIL duplicate/lost store case %d word %d value %h count %d",irqcase,j,mem[j],store_counts[j]);
  if(mem[50]!=0)$fatal(1,"FAIL forbidden branch store");
  @(negedge clk);
 end
 irq_testing=0;reset_case();
 // A taken backward branch targets address zero exactly; its delay slot runs twice.
 rom[0]=encI(9,1,1,1);rom[1]=encI(10,1,2,2);rom[2]=encI(5,2,0,16'hfffd);rom[3]=encI(9,3,3,1);rom[4]=encI(43,0,3,0);
 rst=0;while(mem[0]!==2)@(negedge clk);
 if(dut.regs[1]!=2||dut.regs[3]!=2)$fatal(1,"FAIL target zero/delay slot");
 reset_case();force_wait=1;
 rom[0]=encI(9,0,1,123);rom[1]=encI(43,0,1,0);rst=0;
 while(!dv)@(negedge clk);
 repeat(4)@(negedge clk);
 rst=1;repeat(3)@(negedge clk);
 if(dv||tv||ev||cc||rc||sc||dut.regs[1]||ia)$fatal(1,"FAIL reset during memory wait");
 if(mem[0]!==0)$fatal(1,"FAIL unaccepted store during reset");
 force_wait=0;rst=0;
 while(mem[0]!==123)@(negedge clk);
 $display("PASS pipeline independent traces, waits, 13 precise exception handlers, external/timer IRQ and active reset");$finish;
end
initial begin #2000000;$fatal(1,"FAIL timeout");end
endmodule

tests/tb_soc.sv.text:
`timescale 1ns/1ps
module tb_soc;
 reg clk=0,rst=1,rx=1;
 reg [7:0] switches=0;
 wire tx,buzz,done;
 wire [7:0] led,dn,sn;
 wire [31:0] pc,result,stores;
 localparam CPB=16;
 always #5 clk=~clk;
 lab_soc #(.CLOCK_HZ(160000),.BAUD(10000)) dut(
 .clk(clk),.rst(rst),.uart_rx_pin(rx),.switches(switches),.uart_tx_pin(tx),.led(led),
 .digit_n(dn),.segment_n(sn),.buzzer_pin(buzz),.debug_pc(pc),.debug_result(result),.debug_stores(stores),.debug_done(done));
 task check(input logic ok,input string message);
  if(ok!==1'b1)begin $display("FAIL SOC %s",message);$fatal(1,"SOC assertion");end
 endtask
 task send(input [7:0] data);
  @(negedge clk);rx=0;repeat(CPB)@(negedge clk);
  for(integer b=0;b<8;b++)begin rx=data[b];repeat(CPB)@(negedge clk);end
  rx=1;repeat(CPB)@(negedge clk);
 endtask
 task receive(output reg [7:0] data);
  @(negedge tx);repeat(CPB/2)@(posedge clk);#1;
  check(tx==0,"TX start");
  for(integer b=0;b<8;b++)begin repeat(CPB)@(posedge clk);#1;data[b]=tx;end
  repeat(CPB)@(posedge clk);#1;check(tx==1,"TX stop");
 endtask
 reg [7:0] packet[0:39];
 reg [31:0] values[0:8];
 reg reset_seen,reset_cleared;
 integer restart_wait;
 initial begin
  repeat(5)@(negedge clk);rst=0;
  repeat(200)@(negedge clk);
  check(done && result==89 && stores==12,"Fibonacci architectural outcome");
  check(led==89,"CPU LED MMIO");
  check(dut.display_value==89,"CPU display MMIO");
  @(negedge clk);force dut.da=32'h1f000100;#1;
  check(dut.dr==0,"MMIO address outside documented page reads zero");
  force dut.da=32'h1f000104;force dut.dw=32'ha5;force dut.strb=4'b0001;
  @(posedge clk);#1;check(dut.led_value==89,"MMIO address outside documented page cannot alias LED");
  @(negedge clk);release dut.da;release dut.dw;release dut.strb;
  switches=8'h3c;repeat(40)@(negedge clk);
  check(led==(8'h59^8'h3c),"switch-to-CPU-to-LED");
  check(dut.display_value==32'h003c0059,"switch-to-display");
  fork
   send(8'h3f);
   begin for(integer j=0;j<40;j++)receive(packet[j]);end
  join
  check({packet[3],packet[2],packet[1],packet[0]}==32'h5550434d,"packet signature");
  for(integer j=0;j<9;j++)values[j]={packet[j*4+7],packet[j*4+6],packet[j*4+5],packet[j*4+4]};
  check(values[0]==1 && values[2]==89 && values[4]==12 && values[8]==0,"atomic telemetry");
  check(values[5]==32'h003c0059 && values[6]==32'h00003c65,"telemetry GPIO");
  send(8'h30);repeat(8)@(negedge clk);check(led==0,"UART LEDs off");
  send(8'h31);repeat(8)@(negedge clk);check(led==255,"UART LEDs on");
  send(8'h61);repeat(8)@(negedge clk);check(led==8'h65,"UART auto mode");
  send(8'h62);repeat(8)@(negedge clk);check(dut.beep,"UART beep trigger");
  reset_seen=0;reset_cleared=0;
  fork
   send(8'h72);
   begin
    repeat(CPB*12)begin
     @(posedge clk);
     if(dut.core_rst)begin
      reset_seen=1;#1;
      if(pc==32'h00400000 && dut.cycles==0 && dut.retired==0 && stores==0 && !done && result==0)
       reset_cleared=1;
     end
    end
   end
  join
  check(reset_seen,"UART restart asserts CPU reset");
  check(reset_cleared,"UART restart clears PC and CPU telemetry");
  restart_wait=0;
  while(!(done && stores==12 && result==89) && restart_wait<250)begin
   @(negedge clk);restart_wait=restart_wait+1;
  end
  check(done && stores==12 && result==89,"UART restart recomputes Fibonacci outcome");
  check(dut.errors==0,"no illegal instructions");
  $display("PASS SOC fibonacci=12 uart_packet=40 gpio=3 restart=1");$finish;
 end
 initial begin #3000000;$display("FAIL SOC timeout");$fatal(1,"timeout");end
endmodule

tests/tb_teach_soc.sv.text:
`timescale 1ns/1ps
module tb_teach_soc;
 reg clk=0,resetn=0;
 always #5 clk=~clk;
 wire [6:0] digital_num0,digital_num1;
 wire [7:0] digital_cs,led;
 // Intentionally instantiate the original supplied top without editing its ports.
 teach_soc_top dut(.clk(clk),.resetn(resetn),.mid_btn_key(1'b0),
  .left_btn_key(1'b0),.right_btn_key(1'b0),.up_btn_key(1'b0),
  .down_btn_key(1'b0),.switch(8'hff),.digital_num0(digital_num0),
  .digital_num1(digital_num1),.digital_cs(digital_cs),.led(led));
 integer golden=0,rows=0,cycles=0,got,flag,epoch=0;
 integer bus_stores=0,retired_stores=0,tail_cycles=0,max_cycles=200000;
 reg [31:0] ref_pc,ref_data,ref_rd,tail_pc=32'hbfc00104,tail_value;
 reg [31:0] store_addr[0:65535],store_data[0:65535];
 reg [3:0] store_strobe[0:65535];
 reg completed=0,reset_cancel_checked=0;
 integer trace_file;

 task reopen_golden;
 begin
  if(golden) $fclose(golden);
  golden=$fopen("golden_trace.txt","r");
  if(!golden) $fatal(1,"FAIL TEACH_SOC missing golden trace");
  rows=0;cycles=0;bus_stores=0;retired_stores=0;completed=0;tail_cycles=0;
 end
 endtask

 initial begin
  if($test$plusargs("EARLY_TIMEOUT")) max_cycles=10;
  trace_file=$fopen("teach_retirements.csv","w");
  if(!trace_file) $fatal(1,"FAIL TEACH_SOC trace output open");
  $fdisplay(trace_file,"epoch,cycle,pc,instruction,write_enable,rd,value,store_strobe,store_address,store_value");
  reopen_golden();
  repeat(5) @(negedge clk);
  #1;resetn=1;
  // Cancel the first newly presented store before the memory rising edge.
  wait(dut.cpu_data_en && |dut.cpu_data_wen);
  #1;resetn=0;
  repeat(4) @(negedge clk);
  #1;
  if(bus_stores!=0 || led!==8'hff || dut.confreg.digital_num_v!==0)
   $fatal(1,"FAIL TEACH_SOC reset failed to cancel first store");
  reset_cancel_checked=1;epoch=1;reopen_golden();resetn=1;
 end

 // Actual SRAM/MMIO side effects occur here, half a cycle before CPU handshake.
 always @(posedge clk) begin
  if(!resetn) begin
   if(dut.cpu_inst_en!==0 || dut.cpu_data_en!==0 || dut.cpu_data_wen!==0 || dut.debug_wb_rf_wen!==0)
    $fatal(1,"FAIL TEACH_SOC bus/debug activity in reset");
  end else begin
   if(dut.cpu_inst_wen!==0) $fatal(1,"FAIL TEACH_SOC instruction write");
   if(dut.cpu_data_en && |dut.cpu_data_wen) begin
    if(completed || bus_stores>=65536) $fatal(1,"FAIL TEACH_SOC extra bus store");
    store_addr[bus_stores]=dut.cpu_data_addr;
    store_data[bus_stores]=dut.cpu_data_wdata;
    store_strobe[bus_stores]=dut.cpu_data_wen;
    bus_stores=bus_stores+1;
   end
  end
 end

 // Sample before the falling-edge CPU's nonblocking architectural updates.
 always @(negedge clk) if(resetn) begin
  cycles=cycles+1;
  if(dut.cpu.exception_valid) $fatal(1,"FAIL TEACH_SOC exception code=%0d epc=%h",dut.cpu.exception_code,dut.cpu.exception_epc);
  if(dut.cpu.trace_valid) begin
   // Original test_finish loops through addiu t0,t0,1; b; nop forever.
   // Golden stops after its first addiu. Verify the known tail independently.
   if(completed) begin
    if(dut.debug_wb_pc!==tail_pc) $fatal(1,"FAIL TEACH_SOC unexpected tail pc=%h",dut.debug_wb_pc);
    case(tail_pc)
     32'hbfc00100: begin
      tail_value=tail_value+1;
      if(dut.cpu.trace_instr!==32'h25080001 || dut.debug_wb_rf_wen!==4'hf ||
       dut.debug_wb_rf_wnum!==8 || dut.debug_wb_rf_wdata!==tail_value)
       $fatal(1,"FAIL TEACH_SOC unexpected tail register write");
      tail_pc=32'hbfc00104;
     end
     32'hbfc00104: begin
      if(dut.cpu.trace_instr!==32'h1000fffe || dut.debug_wb_rf_wen!==0)
       $fatal(1,"FAIL TEACH_SOC unexpected tail branch");
      tail_pc=32'hbfc00108;
     end
     32'hbfc00108: begin
      if(dut.cpu.trace_instr!==0 || dut.debug_wb_rf_wen!==0)
       $fatal(1,"FAIL TEACH_SOC unexpected tail delay slot");
      tail_pc=32'hbfc00100;
     end
     default: $fatal(1,"FAIL TEACH_SOC invalid tail state");
    endcase
   end
   $fdisplay(trace_file,"%0d,%0d,%08h,%08h,%0d,%0d,%08h,%01h,%08h,%08h",epoch,cycles,
    dut.debug_wb_pc,dut.cpu.trace_instr,|dut.debug_wb_rf_wen,dut.debug_wb_rf_wnum,
    dut.debug_wb_rf_wdata,dut.cpu.trace_mem_we,dut.cpu.trace_mem_addr,dut.cpu.trace_mem_wdata);
   if(|dut.cpu.trace_mem_we) begin
    if(retired_stores>=bus_stores ||
      {3'b0,dut.cpu.trace_mem_addr[28:0]}!==store_addr[retired_stores] ||
      dut.cpu.trace_mem_wdata!==store_data[retired_stores] ||
      dut.cpu.trace_mem_we!==store_strobe[retired_stores])
     $fatal(1,"FAIL TEACH_SOC store mismatch retirement=%0d bus=%0d",retired_stores,bus_stores);
    retired_stores=retired_stores+1;
   end
  end
  if(!completed && |dut.debug_wb_rf_wen && dut.debug_wb_rf_wnum!=0) begin
   got=$fscanf(golden,"%h %h %h %h",flag,ref_pc,ref_rd,ref_data);
   if(got!=4 || flag!=1 || dut.debug_wb_rf_wen!==4'hf ||
    dut.debug_wb_pc!==ref_pc || {27'b0,dut.debug_wb_rf_wnum}!==ref_rd || dut.debug_wb_rf_wdata!==ref_data)
    $fatal(1,"FAIL TEACH_SOC row=%0d fields=%0d actual=%h/%h/%h expected=%h/%h/%h",rows,got,
     dut.debug_wb_pc,dut.debug_wb_rf_wnum,dut.debug_wb_rf_wdata,ref_pc,ref_rd,ref_data);
   rows=rows+1;
  end
  if(!completed && dut.cpu.trace_valid && dut.debug_wb_pc==32'hbfc00100 && epoch==1) begin
   if(led!==8'h0f || dut.confreg.digital_num_v!==32'h13000013 || !reset_cancel_checked)
    $fatal(1,"FAIL TEACH_SOC final state led=%h display=%h",led,dut.confreg.digital_num_v);
   got=$fscanf(golden,"%h",flag);
   if(got!=-1) $fatal(1,"FAIL TEACH_SOC unconsumed or malformed golden tail fields=%0d",got);
   if(rows!=28970 || bus_stores!=retired_stores)
    $fatal(1,"FAIL TEACH_SOC incomplete rows=%0d stores=%0d/%0d",rows,retired_stores,bus_stores);
   tail_value=ref_data;completed=1;
  end
  if(completed) begin
   tail_cycles=tail_cycles+1;
   if(tail_cycles==32) begin
    $display("PASS TEACH_SOC rows=%0d cycles=%0d stores=%0d display=%h led=%h enabled_points=19 reset_cancel=1 checked_tail=32",
     rows,cycles,bus_stores,dut.confreg.digital_num_v,led);
    $fclose(golden);$fclose(trace_file);$finish;
   end
  end
  if(cycles>max_cycles) $fatal(1,"FAIL TEACH_SOC timeout pc=%h",dut.debug_wb_pc);
 end
 initial begin #2500000; $fatal(1,"FAIL TEACH_SOC absolute timeout"); end
endmodule
